/* DAWAH X — ahmad, অধ্যায় 26 · খণ্ড 26 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][26]=[[5001,5001,"","আমরা একটি সিদ্ধান্তের বাবার কথা বলেছি, যে কিনা নিজের হাতে ঈশ্বরের সাথে কথা বলেছে। যদি মানুষ জানতে পারে যে ইউনিটে কি আছে, তারা কখনো রাতে গাড়ি চালায় না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي الْوَحْدَةِ مَا سَارَ رَاكِبٌ بِلَيْلٍ أَبَدًا ‏","","",""],[5002,5002,"","আমরা একটি পৃথিবীর কথা বলেছি তার বাবাকে ঈশ্বরের কাছে বলা এক পৃথিবীর কথা বলছি আর তিনি শান্তি রক্ষা করবেন না, তার জীবন নিয়ে কোন কুকুরকে কিছু করবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اقْتَنَى كَلْبًا إِلَّا كَلْبَ ضَارٍ أَوْ كَلْبَ مَاشِيَةٍ نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ قِيرَاطَانِ ‏","","",""],[5003,5003,"","আমরা দুই মাস ধরে ঈশ্বরের অনুগ্রহের কথা বলেছি, সে আমাকে মেরে ফেলবে, সে শিকারী কুকুর নয়, না কাঠবিড়াল।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اقْتَنَى كَلْبًا إِلَّا كَلْبَ صَيْدٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ قِيرَاطَانِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏نُقِصَ مِنْ عَمَلِهِ ‏","","",""],[5004,5004,"","আমরা দুই মাস ধরে ঈশ্বরের পুত্র রাজদণ্ড আর ঈশ্বরের কাছে আমার সৌভাগ্যের কথা বলেছি এক বছরের ছেলে। ঈশ্বর তার কাছে প্রার্থনা করেছেন আর অফিসারদের খেতে না বলায় তিনি আত্মসমর্পণ করেছেন। তাকে আর আমি বঞ্চিত করব না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏وَالْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[5005,5005,"","আমরা একে অপরের স্বপ্নের কথা বলেছি একটি গৌরব ফিরে আসার স্বপ্ন, যে বলে আমি এমন এক ছেলের সাথে, যে ইতিমধ্যেই কিছু একটা বিষয় নিয়ে ছিল। আমার ভাই বলেছে, আমার বাবা তার ছেলেকে একটা ছেলে বানিয়েছে। যে এই কৌশলটা করেছে সে বলেছে সে মুক্ত হতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي حَلْقَةٍ قَالَ فَسَمِعَ رَجُلًا فِي حَلْقَةٍ أُخْرَى وَهُوَ يَقُولُ لَا وَأَبِي فَرَمَاهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏بِالْحَصَى فَقَالَ إِنَّهَا كَانَتْ يَمِينَ ‏ ‏عُمَرَ ‏ ‏فَنَهَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهَا وَقَالَ إِنَّهَا شِرْكٌ ‏","","",""],[5006,5006,"","আমরা তার বাবার কাছে কথা বলেছি একটি ছেলে সন্তানের জন্য যিনি তার জীবনের অনেক দায়িত্ব নিয়েছেন এই বলে যে তিনি একটি ছেলে হয়ে গেছেন একটি ছেলে ছেলে পুত্র হয়েছে যে সন ্ তান গ ্ রহণ করা হয়েছে । আমি ঈশ্বরকে সাহায্য করতে এবং তা খুঁজে পেতে দেখেছি এবং হয়তো তাকে ব্যর্থ হতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ جُمْهَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏إِنْ ‏ ‏أَسْعَى فَقَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْعَى وَإِنْ أَمْشِي فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي وَأَنَا شَيْخٌ كَبِيرٌ ‏","","",""],[5007,5007,"","আমরা দু'টো গ্রীষ্মের কথা বলেছি যখন হঠাৎ হঠাৎ করে আমরা একটা ছেলের কথা বলেছি যে তার জন্য ঈশ্বরের কাছে প্রার্থনা করেছে আর সে বলবে যদি তিন সেকেন্ড হয়, সে দুই ধরণের ঋণ তৈরি করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَنْتَجِي ‏ ‏اثْنَانِ دُونَ وَاحِدٍ ‏","","",""],[5008,5008,"","আমরা দুই মাস ধরে ঈশ্বরের পুত্র সম্পর্কে কথা বলেছি, যে কিনা ভগবানের হাতে নিহত হয়েছে। হয় ভাই, তুমি তার ভাইকে হারাতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرِئٍ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهَا أَحَدُهُمَا ‏","","",""],[5009,5009,"","আমরা একটি ছেলে কথা বলেছি যে কিনা ঈশ্বরকে কখনো না বলে ভাল ছেলে, পুরুষ আছে একজন মানুষ আছে, আমার আছে একজন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ غَزْوَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا رَجُلٍ كَفَّرَ رَجُلًا فَأَحَدُهُمَا كَافِرٌ ‏","","",""],[5010,5010,"","আমরা দুই মাস ধরে কথা বলেছি আর ক্ষমার জন্য সব থেকে ভালো লাগছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার প্রভুকে মাফ করে দিবো আর তার কথা মেনে চলবেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارُ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَعُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏","","",""],[5011,5011,"","আমরা সুখী ছেলের জন্য কথা বলেছি... ...তার প্রতি ঈশ্বরের ইচ্ছা আছে আর তাকে তার জীবনের জীবনের উপর অত্যাচার করতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الْوَلِيدِ بْنِ عُبَادَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يُنَحْ عَلَيْهِ فَإِنَّهُ يُعَذَّبُ بِمَا نِيحَ عَلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5012,5012,"","আমরা একটি ছেলের জন্য দীর্ঘ সময় ধরে কথা বলেছি যে ঈশ্বর যাকে স্বপ্নের কথা কখনো দেখেননি, তাকে ছেড়ে দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْعُمَرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يُجِبْ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[5013,5013,"","আমরা একটা যুদ্ধের পাথরের কথা বলেছি... ...আর ওমরের ছেলের কথা শুনে... ...আপনার শ্রদ্ধা তোমার নিয়ন্ত্রণে নেই, ঈশ্বরের কাছে প্রার্থনা করো আর আমার কাছে আত্মসমর্পণ করো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَفْعَكُمْ أَيْدِيَكُمْ بِدْعَةٌ مَا زَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذَا ‏ ‏يَعْنِي إِلَى الصَّدْرِ ‏","","",""],[5014,5014,"","আমরা তার বাবার অনেক নরকের কথা বলেছি, তিনি বলেছেন আমি আমার শিরায় একটা ছেলে হাঁটছি। এই আলোমর এবং গৌরব বলতে পারব না যে আমি হয়তো ঈশ্বরকে দেখেছি। আমি দেখেছি, আমি দেখেছি। লর্ড তার কাছে প্রার্থনা করবে এবং আমি হাঁটবো এবং আমরা scing হবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ جُمْهَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَمْشِي فِي ‏ ‏الْوَادِي ‏ ‏بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَلَا ‏ ‏يَسْعَى فَقُلْتُ لَهُ فَقَالَ إِنْ أَسْعَ فَقَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْعَى وَإِنْ أَمْشِ فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي وَأَنَا شَيْخٌ كَبِيرٌ ‏","","",""],[5015,5015,"","আমরা দুই বছর ধরে আমার বাবার কাছে এক টাকার কথা বলেছি... ...তার ছেলে হবে... ...যে কখনো ছেলে হবে না, আমি তাকে কিছু জিজ্ঞেস করার সাহস রাখি। তার পেন্সিল বা তার মার খাওয়ার কারণে তার যন্ত্রণা কমে গিয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَعْتَقَ عَبْدًا لَهُ فَقَالَ مَا لِي مِنْ أَجْرِهِ وَتَنَاوَلَ شَيْئًا مِنْ الْأَرْضِ مَا يَزِنُ هَذِهِ ‏ ‏أَوْ مِثْلَ هَذِهِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَطَمَ غُلَامَهُ ‏ ‏أَوْ ضَرَبَهُ ‏ ‏فَكَفَّارَتُهُ عِتْقُهُ ‏","","",""],[5016,5016,"","আমরা দুজন ছেলের ব্যাপারে কথা বলেছি যারা আমাকে বলেছিল বাবা একটা ছেলে থাকার অসুস্থ ছিল, তার একটা আংটি আছে আর তারপর সে বলেছে আমি কি করবো বা কী করব ( খ) কীভাবে আমরা জানি যে, আমরা ঈশ্বরের প্রতি অনুগত?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَدَعَا غُلَامًا لَهُ فَأَعْتَقَهُ ثُمَّ قَالَ مَا لِي فِيهِ مِنْ أَجْرٍ مَا يَسْوَى هَذَا ‏ ‏أَوْ يَزِنُ هَذَا ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ضَرَبَ عَبْدًا لَهُ ‏ ‏حَدًّا ‏ ‏لَمْ يَأْتِهِ ‏ ‏أَوْ ظَلَمَهُ أَوْ لَطَمَهُ شَكَّ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَإِنَّ كَفَّارَتَهُ أَنْ يُعْتِقَهُ ‏","","",""],[5017,5017,"","আমরা একটি ভয়ানক ছেলে হতে কথা বলেছি এবং সে এটা পেতে চেষ্টা করছিল. আমি ভুলে গিয়েছিলাম Seren একটি ছেলের সাথে কথা বলতে যে তিনি তালাক পেয়েছেন যে তিনি একটি ভাল স্বপ্ন. তিনি বললেন. তিনি বলেন. তিনি বলেন. তিনি একটি ভাল জানেন. আমি এটা ছিল. আমি ভুলে গিয়েছিলাম. আমি ভুলে গিয়েছিলাম. আমি ভুলে গিয়েছিলাম. আমি ভুলে গিয়েছিলাম. আমি ভুলে গিয়েছিলাম. আমি ভুলে গিয়েছিলাম যে Seren. আমি জানি আপনি কি জানেন না যে Seren. আমি জানি না যে Sher. আমি জানি না যে আপনি জানেন যে আপনি জানেন না. আমি ভাল জানেন. আমি ভাল জানেন. আমি আপনাকে একটি মহান. আমি আপনাকে যে আপনি একটি মহান একটি ছেলে. আমি জানি. আমি জানি. আমি জানি যে আপনি একটি মহান. আমি জানি যে আপনি জানেন যে আপনি জানেন না. আমি একটি মহান. আমি আপনাকে একটি মহান. আমি একটি মহান. আপনি একটি মহান. আমি আপনাকে একটি মহান পিতা. আপনি জানেন যে আপনি জানেন. আমি আপনাকে বলেন. আমি একটি মহান সময়. আমি আপনাকে একটি মহান সময়. আপনি জানেন. আমি আপনাকে একটি মহান একটি মহান সময়. আপনি একটি মহান সময়. আপনি একটি মহান সময়. আমি একটি মহান. আপনি একটি মহান একটি মহান একটি মহান, এবং তিনি বলেন যে তিনি বলেন যে তিনি বলেন যে তিনি বলেন যে তিনি বলেন যে তিনি বলেন. আপনি একটি মহান বিবাহ তাকে ফিরিয়ে আন, তাই সে পরিষ্কার করে বলল সে ভয় পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَسَأَلَ ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا فَإِذَا طَهُرَتْ فَلْيُطَلِّقْهَا ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَتُحْتَسَبُ ‏","","",""],[5018,5018,"","আমরা একটা সাহসী ছেলের কথা বলেছি যে বলেছে সে হয়তো সবার সেরা। যে কিনা ভালোর বাবা মারা গেছে। এই ভবিষ্যদ্বাণীটা পড়ে দেখুন এবং সেগুলো করার জন্য বলা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَيْمَنَ ‏ ‏يَسْأَلُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَبُو الزُّبَيْرِ ‏ ‏يَسْمَعُ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏قَرَأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمْ النِّسَاءَ فَطَلِّقُوهُنَّ ‏} ‏فِي قُبُلِ عِدَّتِهِنَّ ‏","","",""],[5019,5019,"","আমরা বাবার কাছে তার লেখা বই সম্পর্কে কথা বলেছি, তিনি বলেছিলেন, তিনি একবার লর্ডের অনুগ্রহে পাস করেছেন। ওকে স্পর্শ করতে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَذَكَرَ ذَلِكَ إِلَى ‏ ‏عُمَرَ ‏ ‏فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُمْسِكْهَا ‏ ‏حَتَّى تَحِيضَ غَيْرَ هَذِهِ الْحَيْضَةِ ثُمَّ تَطْهُرَ فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا فَلْيُطَلِّقْهَا كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ وَإِنْ بَدَا لَهُ أَنْ ‏ ‏يُمْسِكَهَا ‏ ‏فَلْيُمْسِكْهَا ‏","","",""],[5020,5020,"","আমরা দুই মাস ঈশ্বরের আশীর্বাদের কথা বলেছি, যিনি বলেছিলেন প্রভু আমার সন্তানদের কাছে এসেছেন। ঈশ্বর বলেছেন, ঈশ্বর আছে এবং বলবে, প্রভু, আমি আপনার কথা বিক্রি করে দেব ব্যর্থ.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُخْدَعُ فِي الْبَيْعِ فَقَالَ ‏ ‏إِذَا بِعْتَ فَقُلْ لَا ‏ ‏خِلَابَةَ ‏","","",""],[5021,5021,"","আমরা একটা পরিস্থিতির কথা বলেছি যা আমি একটা স্বপ্ন শুনেছি যে তালাকপ্রাপ্ত একজন লোককে নিয়ে যে কিনা তালাক পেয়েছে আর তার কিছু হারিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏وَسُئِلَ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ لَا يَجُوزُ طَلَّقَ ‏ ‏ابْنُ عُمَرَ ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ ‏ ‏فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُرَاجِعَهَا فَرَاجَعَهَا ‏","","",""],[5022,5022,"","আমরা একটা পরিস্থিতির কথা বলছিলাম, যখন আমি শুনেছি যে ঈশ্বর এটা করতে যাচ্ছে বলে আমি শুনেছি, ঈশ্বর বলে যে তিনি এটা করবেন। ঈশ্বর আছে এবং তিনি বলছেন আপনি বস্তু বিক্রি করবেন না। আপনি যদি না হয়, আপনি ষাঁড় বিক্রি করবেন। আপনি কি জানেন? আপনি যদি না? আপনি কিছুই বিক্রি করেন? আপনি জানেন না? আপনি জানেন, আপনি কি বলেন, আপনি জানেন না? আপনি জানেন, আপনি কি বলেন, আপনি জানেন, আপনি জানেন না যে আপনি কি আছে, আপনি কি আছে, আপনি জানেন না? আপনি কি? আপনি জানেন, আপনি জানেন না যে, আপনি কিছুই করেন না মনে হচ্ছে ওর ওকের মতো।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَبِيعُوا الثَّمَرَ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[5023,5023,"","আমরা রাজার মাধ্যমে কথা বলেছি যে আপনার টাকা নিয়ে ঈশ্বরের কাছে এসে একটা ছেলের জন্ম দিয়েছে। সে কিছু বলে নি, তাকে খুন করতে হবে এবং চুরি করতে হবে। অথবা ভাগ্য বলতে পারি, যে আমার মনে আছে সে হচ্ছে একজন বেমানান যে ঈশ্বরকে বলছে ঈশ্বর তার কাছে এসে তাকে ভিতরে আসতে বলছেন। সে বলল, আমি তার কাছ থেকে অনেক বেশি পছন্দ করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا شَجَرَةٌ لَا يَسْقُطُ وَرَقُهَا وَهِيَ مِثْلُ الْمُؤْمِنِ ‏ ‏أَوْ قَالَ الْمُسْلِمِ ‏ ‏قَالَ فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ ‏ ‏قَالَ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِعُمَرَ ‏ ‏فَقَالَ ‏ ‏لَأَنْ تَكُونَ قُلْتَهَا كَانَ أَحَبَّ إِلَيَّ مِنْ كَذَا وَكَذَا ‏","","",""],[5024,5024,"","আমরা কথা বলেছি, ঈশ্বরের ছেলের বাবার দোহাই একবারের জন্য তার ছেলের দেখা পাওয়া সবচেয়ে ভালো কথা, ঈশ্বরের কাছে শপথটা রেখে বলতে হবে যে সে তার ভাগ্য হারাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏النَّذْرِ ‏ ‏وَقَالَ إِنَّهُ لَا يَرُدُّ مِنْ الْقَدَرِ شَيْئًا وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[5025,5025,"","আমরা একটা ছেলের চেয়ে ভালোর জন্য দুটো জীবনের সেরাটা নিয়ে কথা বলেছি, যে কিনা ঈশ্বরের নিকট থেকে এসেছে। সে এমন এক লোককে পাঠিয়েছে যারা আমাকে হুমকি দিবে এবং সে ভদ্র হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏يَهُودِيًّا وَيَهُودِيَّةً ‏ ‏بِالْبَلَاطِ ‏","","",""],[5026,5026,"","আমরা দুজন ছেলের কথা বলেছি, প্রভুর ছেলেকে ধরার জন্য তার কাছে একটা লোক আছে, তার বিবাহ বিচ্ছেদ হয়েছে এবং তারপর বিয়ে হবে, তারপর সে জঙ্গলে চলে গেছে কিন্তু ঈশ্বরের একজন পুত্র হিসেবে জন্মগ্রহণ করার জন্য যাকে ঈশ্বরের রাজা হওয়ার কথা বলা হয়েছে, তাকেই ঈশ্বরের রাজা হতে বলা হয়েছে । এমন একজন মানুষ যে কখনো এ রকম ঘটনা দ্বারা আক্রান্ত হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏رَزِينٍ الْأَحْمَرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ ثَلَاثًا ثُمَّ تَزَوَّجَهَا رَجُلٌ فَأَغْلَقَ الْبَابَ وَأَرْخَى السِّتْرَ وَنَزَعَ الْخِمَارَ ثُمَّ طَلَّقَهَا قَبْلَ أَنْ يَدْخُلَ بِهَا تَحِلُّ لِزَوْجِهَا الْأَوَّلِ فَقَالَ ‏ ‏لَا حَتَّى يَذُوقَ ‏ ‏عُسَيْلَتَهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ رَزِينٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ يَخْطُبُ النَّاسَ عَنْ رَجُلٍ فَارَقَ امْرَأَتَهُ بِثَلَاثٍ فَذَكَرَ مَعْنَاهُ ‏","","",""],[5027,5027,"","আমরা আমাদের সব থেকে ভালো কথা বলেছি, তার ছেলের জন্য মরুভূমি সম্পর্কে তোমার টাকা দিয়ে আমরা যা করেছি, তা নিয়ে কথা বলেছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَرْفَعُ يَدَيْهِ إِذَا اسْتَفْتَحَ الصَّلَاةَ وَإِذَا أَرَادَ أَنْ يَرْكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَلَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ ‏","","",""],[5028,5028,"","আমি আমার দুই ধরনের ঈশ্বরের কাছে একজন দেবীর পুত্র সঙ্গে ঈশ্বরের কাছে যাওয়ার ব্যাপারে আমার সর্বোত্তম উপায় সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَسْتُ بِآكِلِهِ وَلَا مُحَرِّمِهِ ‏","","",""],[5029,5029,"","এরপর তিনি তাকে শান্ত হতে বলেছিলেন, ঈশ্বর তাকে প্রার্থনা করেছেন এবং তিনি দু বছর ধরে তার জন্য অনেক কিছু করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَا وَرَجُلٌ آخَرُ فَدَعَا رَجُلًا آخَرَ ثُمَّ قَالَ ‏ ‏اسْتَرْخِيَا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَنْتَجِيَ ‏ ‏اثْنَانِ دُونَ وَاحِدٍ ‏","","",""],[5030,5030,"","আমরা আমাদের সর্বোত্তমটা নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا بَايَعْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ ‏ ‏يُلَقِّنُنَا ‏ ‏أَوْ يُلَقِّفُنَا ‏ ‏فِيمَا اسْتَطَعْتَ ‏","","",""],[5031,5031,"","আমরা ঈশ্বরের ছেলের সবচেয়ে ভালো দুই তলোয়ারের কথা বলেছিলাম... ...ঈশ্বরের কাছে তার ছেলেকে বলতে শুনেছি... ...তার ভাগ্যের রাতের জন্য ছেড়ে দিতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لَيْلَةِ الْقَدْرِ فَقَالَ ‏ ‏تَحَرَّوْهَا فِي السَّبْعِ الْأَوَاخِرِ ‏","","",""],[5032,5032,"","আমাদের লোকেরা ঈশ্বরের কাছে প্রতিজ্ঞা করেছিল যে, ভেনিসে আমাদের এই ভয়কে ব্যর্থ করবে । কথা বলো.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَتَّقِي كَثِيرًا مِنْ الْكَلَامِ ‏ ‏وَالِانْبِسَاطِ إِلَى نِسَائِنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَخَافَةَ أَنْ يَنْزِلَ فِينَا الْقُرْآنُ فَلَمَّا مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَكَلَّمْنَا ‏","","",""],[5033,5033,"","আমরা একটা ছেলের জন্য দুইটা তলোয়ারের কথা বলেছি, যে কিনা ঈশ্বরের দ্বারা পাস করেছে। সে আমাকে রাতে ফোন করে আর আমার মায়ের নাম শুনে ভেঙেছে। বাবা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5034,5034,"","আমি আমার সন্তানদের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম । প্রভুর ইচ্ছার উপর ভিত্তি করে কাজ করা, বুঝতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْأَنْفَالِ ‏ ‏لِلْفَرَسِ ‏ ‏سَهْمَيْنِ ‏ ‏وَلِلرَّجُلِ ‏ ‏سَهْمًا ‏","","",""],[5035,5035,"","আমরা তোমার টাকার সেরাটা বলেছি আমার ঈশ্বরের পুত্রের চেয়ে ফুল এর জন্য... ...আমার কাছের টাকার জন্য... ...আমার কাছে এটা কখনোই তৈরি হয়নি, সূর্যাস্ত প্রার্থনা করেছে আর ডিনার সব ঠিক আছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الْمَغْرِبَ وَالْعِشَاءَ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏جَمِيعًا ‏","","",""],[5036,5036,"","আমরা যে - সমস্ত ভালো কাজ করেছি, তা হল, ঈশ্বরের কাছে পাঠানো একটা ছেলের জন্য টাকা পাওয়ার সবচেয়ে ভাল উপায় ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فَغَنِمُوا إِبِلًا كَثِيرَةً فَبَلَغَتْ سِهَامُهُمْ أَحَدَ عَشَرَ بَعِيرًا ‏ ‏أَوْ اثْنَيْ عَشَرَ بَعِيرًا ‏ ‏وَنُفِّلُوا ‏ ‏بَعِيرًا بَعِيرًا ‏","","",""],[5037,5037,"","আমরা টাকার কথা বলেছিলাম, যে কিনা ঈশ্বরকে রক্ষা করেছে আর সে এটা সম্পর্কে স্বপ্ন দেখে গেছে। সেলাই বলেছিল তোমার টাকা আর তোমার জেদ তোমাকে খুব ভালো করে দেবে। মেয়ে আর আমি আমার মেয়েকে ঘৃণা করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الشِّغَارِ ‏ ‏قَالَ ‏ ‏مَالِكٌ ‏ ‏وَالشِّغَارُ ‏ ‏أَنْ يَقُولَ أَنْكِحْنِي ابْنَتَكَ وَأُنْكِحُكَ ابْنَتِي ‏","","",""],[5038,5038,"","আমরা আমাদের সর্বোত্তমটা সম্বন্ধে বলেছিলাম, যা সূর্যের দ্বারা সাহায্য লাভ করা হয়েছিল । তোমারটা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏وَسَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ ‏ ‏صَلَّى الْمَغْرِبَ ‏ ‏بِجَمْعٍ ‏ ‏وَالْعِشَاءَ بِإِقَامَةٍ ثُمَّ حَدَّثَ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ صَنَعَ مِثْلَ ذَلِكَ وَحَدَّثَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ مِثْلَ ذَلِكَ ‏","","",""],[5039,5039,"","আমরা আপনার টাকা একটি ছেলের জন্য যে ছেলে নিহত হয়েছে তার সম্পর্কে কথা বলেছি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏رَجُلَانِ ‏ ‏مِنْ الْمَشْرِقِ فَخَطَبَا فَعَجِبَ النَّاسُ مِنْ بَيَانِهِمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَعْضَ ‏ ‏الْبَيَانِ ‏ ‏سِحْرٌ ‏ ‏أَوْ إِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا ‏","","",""],[5040,5040,"","আমরা যে - সমস্ত জিনিস পেয়েছি, সেগুলোর মধ্যে একটা ছিল, আমাদের ছেলে ঈশ্বরের কাছে পাঠানো এক ছেলের জন্য সবচেয়ে ভালো টাকা ছিল আর তিনি তা ছিলেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الثَّمَرَةِ ‏ ‏حَتَّى يَبْدُوَ صَلَاحُهَا نَهَى الْبَائِعَ وَالْمُشْتَرِيَ ‏","","",""],[5041,5041,"","আমরা এমন এক ছেলের জন্য সবচেয়ে ভালো যে - টাকা আমরা পেয়েছিলাম, তার জন্য সে ঈশ্বরের কাছে পাঠানো হয়েছে, তার নাম ঈশ্বর ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُسَافَرَ بِالْقُرْآنِ إِلَى أَرْضِ الْعَدُوِّ مَخَافَةَ أَنْ يَنَالَهُ الْعَدُوُّ ‏","","",""],[5042,5042,"","আমরা টাকার কথা বলেছি, যে কিনা কিনা ঈশ্বরের হয়ে কাজ করতো আর সে স্বপ্ন দেখে। তুমি পাহাড় দেখতে না আসা পর্যন্ত আটকে ছিলে, এমনকি তুমি ভাবতেও পারবেনা যে তারা হবে খুবই সাহসী।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ وَلَا تُفْطِرُوا حَتَّى تَرَوْهُ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَاقْدُرُوا لَهُ ‏","","",""],[5043,5043,"","আমরা একটা ছেলের জন্য টাকা নিয়ে কথা বলেছি, যে ঈশ্বরকে রক্ষা করেছে আর সে স্বপ্নে দেখেছে যে সে কত কিছু করেছে। সে একটা পাহাড়ের নিচে পড়ে গিয়েছিল অথবা একটা বিয়ের আয়োজন করেছিল। রাজা তার সঙ্গে দেখা করতে আসেন এবং আরও কয়েক বার দৌড়ে আসেন এবং এরপর তিনি বলেন যে তিনি কখনো তা করবেন না । একত্রিত কর।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ حَجٍّ أَوْ عُمْرَةٍ أَوْ غَزْوٍ ‏ ‏كَبَّرَ عَلَى كُلِّ ‏ ‏شَرَفٍ ‏ ‏مِنْ الْأَرْضِ ثَلَاثًا ثُمَّ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ سَاجِدُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ اللَّهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏","","",""],[5044,5044,"","আমরা যে - ভাইদের কাছে যাই, তাদের জন্য সবচেয়ে ভাল টাকা ছিল, তাদের কাছে আমরা সবচেয়ে ভাল বিষয়টা নিয়ে কথা বলতাম । তার বাড়িতে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي قَبْلَ الظُّهْرِ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ وَبَعْدَ الْمَغْرِبِ رَكْعَتَيْنِ فِي بَيْتِهِ وَبَعْدَ الْعِشَاءِ رَكْعَتَيْنِ وَبَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ فِي بَيْتِهِ ‏","","",""],[5045,5045,"","নকল এবং নকল অক্সিজেন কিনছে প্রতিদিন রুটি দিয়ে দিন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُزَابَنَةُ ‏ ‏اشْتِرَاءُ الثَّمَرِ بِالتَّمْرِ كَيْلًا ‏ ‏وَالْكَرْمِ ‏ ‏بِالزَّبِيبِ كَيْلًا ‏","","",""],[5046,5046,"","আমরা একটা ছেলের জন্য আপনার পয়সার সর্বোত্তমটা নিয়ে কথা বলেছিলাম, যিনি বিয়ের মাঝামাঝি সময়ে বাইরে গিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏خَرَجَ فِي ‏ ‏فِتْنَةِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏وَقَالَ ‏ ‏إِنْ نُصَدَّ عَنْ ‏ ‏الْبَيْتِ ‏ ‏صَنَعْنَا كَمَا صَنَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5047,5047,"","আমরা আপনার টাকা একটি ছেলের জন্য সব সম্পর্কে কথা বলেছি যে কিনা তালাক আছে এবং শেষ হয়েছে. আমি যা পেয়েছি, তা নিয়ে চিন্তা করুন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَسَأَلَ ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ ‏ ‏يُمْسِكْهَا ‏ ‏حَتَّى تَطْهُرَ ثُمَّ تَحِيضَ ثُمَّ تَطْهُرَ ثُمَّ إِنْ شَاءَ طَلَّقَهَا وَإِنْ شَاءَ ‏ ‏أَمْسَكَهَا ‏ ‏فَتِلْكَ الْعِدَّةُ الَّتِي أَمَرَ اللَّهُ أَنْ يُطَلَّقَ لَهَا النِّسَاءُ ‏","","",""],[5048,5048,"","আমরা আপনার টাকা একটি ছেলের জন্য যে বড় হয়েছে তার জন্য আপনার ছেলে সম্পর্কে কথা বলেছি তিনি আমাকে হুমকি দিচ্ছেন.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏يَهُودِيًّا وَيَهُودِيَّةً ‏","","",""],[5049,5049,"","আমি আপনার টাকা দিয়ে বলছি যে, ভাববাদীর সঙ্গে তা করা উচিত এবং তিনি তা করার জন্য আপনাকে যে - টাকা দিয়েছেন, তা তিনি এই নিশ্চয়তা দিয়েছিলেন যে, আপনি কখনোই মুক্তি পাবেন না । আমি তোমার টাকার জন্য শোক প্রকাশ করেছি, যখন ঈশ্বর বলেছিলেন আমরা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَتَحَرَّيَنَّ أَحَدُكُمْ فَيُصَلِّيَ قَبْلَ طُلُوعِ الشَّمْسِ وَلَا عِنْدَ غُرُوبِهَا قُلْتُ ‏ ‏لِمَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[5050,5050,"","আমরা সেই ছেলের জন্য আপনার পয়সার সর্বোত্তমটা নিয়ে কথা বলেছিলাম, যিনি সেই ছেলের জন্য হাল ছেড়ে দেওয়ার জন্য অনুরোধ করেছিলেন । ভ্রমণকারী.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا كَانَتْ لَيْلَةُ رِيحٍ وَبَرْدٍ فِي سَفَرٍ أَمَرَ الْمُؤَذِّنَ فَأَذَّنَ ثُمَّ قَالَ ‏ ‏الصَّلَاةُ فِي الرِّحَالِ ‏","","",""],[5051,5051,"","আমরা আপনাদের টাকা ঈশ্বরের কাছে উদ্ধার করতে পালিয়ে গিয়েছিলাম এমন এক ছেলের জন্য যে - ছেলে ঈশ্বরের কাছে পালিয়ে গিয়েছিল । এবং উপাসনা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏فَرَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَةَ ‏ ‏الْفِطْرِ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ عَنْ كُلِّ ذَكَرٍ وَأُنْثَى وَحُرٍّ وَعَبْدٍ مِنْ الْمُسْلِمِينَ ‏","","",""],[5052,5052,"","আমরা আপনার টাকা সম্পর্কে কথা বলেছি, যে তার জন্য এসেছে তার জন্য আপনার সন্তানের জন্য। এমনকি তরল পদার্থও মুছে গেছে এবং জীবিত হয়ে গেছে এবং কিছু জিনিস বিক্রি করছে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏تَلَقِّي السِّلَعِ ‏ ‏حَتَّى يُهْبَطَ بِهَا الْأَسْوَاقُ وَنَهَى عَنْ ‏ ‏النَّجْشِ ‏ ‏وَقَالَ لَا يَبِيعُ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ ‏","","",""],[5053,5053,"","আমরা আপনাদের টাকাপয়সা সম্বন্ধে বলেছিলাম, যে - ছেলে ঈশ্বরের সবচেয়ে ভাল সন্তান হওয়ার জন্য জন্মগ্রহণ করেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏عَجِلَ ‏ ‏بِهِ السَّيْرُ ‏ ‏جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[5054,5054,"","আমরা আপনার সবচেয়ে ভালো টাকা নিয়ে কথা বলেছি, যে ছেলের কাছে যে টাকা ছিল তার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَاعَ نَخْلًا قَدْ ‏ ‏أُبِرَتْ ‏ ‏فَثَمَرَتُهَا لِلْبَائِعِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏","","",""],[5055,5055,"","আমরা আপনার টাকা একটি ছেলের জন্য কাজ করার জন্য যে ছেলে এসেছে এবং তাকে ভালবাসা দিয়েছি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏","","",""],[5056,5056,"","আমরা আপনাদের টাকা নিয়ে কথা বলেছি, যে ছেলে কাপড়ের রক্ষককে টাকা দিতে হয়েছে। সে বলেছে শার্ট না পরে, মাস্টাররা তাদেরকে খেলবে আর খেলবে। কাপড়ের পোশাক পরনি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَلْبَسُ الْمُحْرِمُ مِنْ الثِّيَابِ قَالَ ‏ ‏لَا تَلْبَسُوا الْقُمُصَ وَلَا الْعَمَائِمَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا السَّرَاوِيلَاتِ وَلَا الْخِفَافَ إِلَّا مَنْ لَا يَجِدُ نَعْلَيْنِ فَيَقْطَعُهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا تَلْبَسُوا مِنْ الثِّيَابِ مَا ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏أَوْ ‏ ‏زَعْفَرَانٌ ‏","","",""],[5057,5057,"","আমরা আপনার সবচেয়ে ভালো টাকা নিয়ে কথা বলেছি যে ছেলে ঈশ্বরের দোহাই দিয়ে এসেছে আর তাকে কেউ সাহায্য করেছে যে ছেলে হিসেবে আছে। একটি ছেলে ছেলে পুত্র হয়েছে যে সন ্ তান গ ্ রহণ করেছে , তার জন ্ যে সন্তান রয়েছে একটা ছেলে , যেহেতু সন্তান হয়েছে একটা ছেলে । সে খাবার কিনে ফেলেছে, তার যাওয়ার আগ পর্যন্ত সে এটা বিক্রি করবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏ابْتَاعَ طَعَامًا فَلَا يَبِيعُهُ حَتَّى ‏ ‏يَسْتَوْفِيَهُ ‏","","",""],[5058,5058,"","আমরা একটা ছেলের জন্য কাজ করার জন্য আপনার টাকা সম্পর্কে কথা বলেছি যে এটা করেছে, তারপর তার তিনটা স্কুল আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[5059,5059,"","আমরা আপনাদের টাকা দিয়ে একটা ছেলের জন্য বানানো একটা ছেলের জন্য সবকিছু নিয়ে কথা বলেছিলাম, যাকে বলা হয়েছিল যেতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[5060,5060,"","আমরা আপনার টাকার কথা বলছি একটি ছেলের জন্য যার জন্য তাকে থামাতে হবে, ঈশ্বরের অনুগ্রহ তার নিজের জন্য এবং তিনি তার মায়ের জন্মকে চূর্ণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا لَاعَنَ امْرَأَتَهُ ‏ ‏وَانْتَفَى ‏ ‏مِنْ وَلَدِهَا ‏ ‏فَفَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُمَا وَأَلْحَقَ الْوَلَدَ بِأُمِّهِ ‏","","",""],[5061,5061,"","তিনি বলেছিলেন যে, আশীর্বাদের একেবারে শেষ পর্যায়ে পড়েছি: আপনার বাবা আমাকে বলেছিলেন: আপনার কাছে একবার যা ঘটেছে, সেই অস্বস্থিকর মধ্যে দিয়ে আমার সঙ্গে কথা বলুন । শব্দের সাহায্যে আপনি বজ্র জয়ে গ্রাস করছেন.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنِي ‏ ‏حَمَّادٌ الْخَيَّاطُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[5062,5062,"","তিনি বলেছিলেন, আপনার সবচেয়ে ভালো টাকার কথা, ঈশ্বরের পুত্র সম্পর্কে আমি পড়েছি। ঈশ্বর তাকে আদেশ দিয়েছেন তাকে তার পালনকর যেন তার কাছে সমর্পণ করতে। আলো মুছে আপনার মন ধুয়ে ফেলুন এবং তারপর আমরা ঘুমাবো।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ ذَكَرَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ تُصِيبُهُ جَنَابَةٌ مِنْ اللَّيْلِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأْ وَاغْسِلْ ذَكَرَكَ ثُمَّ نَمْ ‏","","",""],[5063,5063,"","তিনি বললেন ক্ষমার অযোগ্যতার জন্য আমি পড়েছি: ঈশ্বর ভুলে যাওয়ার পর আপনার টাকা এটা সম্পর্কে ভুলে যাওয়ার পর, সে তাকে যেভাবে দেখবে সেভাবে বানরের মত সে আপনাকে স্পর্শ করবে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ صَاحِبِ الْقُرْآنِ كَمَثَلِ صَاحِبِ الْإِبِلِ ‏ ‏الْمُعَقَّلَةِ ‏ ‏إِنْ ‏ ‏عَاهَدَ ‏ ‏عَلَيْهَا أَمْسَكَهَا وَإِنْ أَطْلَقَهَا ذَهَبَتْ ‏","","",""],[5064,5064,"","ঈশ্বর বলেন, আমি সারা রাত ধরে ড্রিংক করি । আমার মা একটা ছেলেকে ডাকে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5065,5065,"","আমরা দুটো বাপ্তিস্ম নিয়ে কথা বলেছি... ...আমাদের প্রভুকে বড় করার জন্য তিন মাস ধরে আমরা আমার প্রভুর সাথে তিন মাস কাজ করেছি। সে বলল, আমি একটা জীবিত থাকার জন্য পাগল হয়ে যাবো, যে তার অশুভ শক্তি আর তার চাকর আর তার চাকরের দিকে তাকিয়ে থাকবে ঈশ্বর আগামীকাল তার চেহারা দেখে... ...আর তার এই কল্পনার পরে আবার বেঁচে উঠবে.","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثُوَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً الَّذِي يَنْظُرُ إِلَى جِنَانِهِ وَنَعِيمِهِ وَخَدَمِهِ وَسُرُرِهِ مِنْ مَسِيرَةِ أَلْفِ سَنَةٍ وَإِنَّ أَكْرَمَهُمْ عَلَى اللَّهِ مَنْ يَنْظُرُ إِلَى وَجْهِهِ ‏ ‏غُدْوَةً ‏ ‏وَعَشِيَّةً ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا ‏ ‏نَاظِرَةٌ ‏ }","","",""],[5066,5066,"","আমরা দুজন বাপ্তিস্মের কথা বলেছি... ...ঈশ্বরের অনুগ্রহে আবদ্ধ হয়ে আছে. “কোন কোন ব্যক্তি ধার্মিকতা হতে পারে” তাদের কানের সাথে তুলনা করতে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏رَفَعَ الْحَدِيثَ فِي قَوْلِهِ تَعَالَى ‏ { ‏يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ ‏} ‏قَالَ ‏ ‏يَقُومُونَ يَوْمَ الْقِيَامَةِ فِي ‏ ‏الرَّشْحِ ‏ ‏إِلَى أَنْصَافِ آذَانِهِمْ ‏","","",""],[5067,5067,"","আমরা কথা বলেছিলাম তার নিজের চোখে দেখতে দেখতে সুন্দর ছেলেকে নিয়ে, আমার বাবা মৃত হয়ে তার সাহায্যের সাথে কিছু কাজ বিক্রি করে। এমনকি যদি সে শেষ যুদ্ধে তার মুখ দিয়ে ফিরে যায়। তার গাল, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আপনার আত্মার জন্য আত্মসমর্পণ করবেন আমি তার প্রার্থনা প্রার্থনা করব এবং তাকে তার কাছে পৌঁছে দেব.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُكْرِي ‏ ‏أَرْضَهُ عَلَى عَهْدِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏وَبَعْضَ عَمَلِ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ وَلَوْ شِئْتُ قُلْتُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَ فِي آخِرِ إِمَارَةِ ‏ ‏مُعَاوِيَةَ ‏ ‏بَلَغَهُ عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏حَدِيثٌ فَذَهَبَ وَأَنَا مَعَهُ فَسَأَلَهُ عَنْهُ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ فَتَرَكَ أَنْ ‏ ‏يُكْرِيَهَا ‏ ‏فَكَانَ إِذَا سُئِلَ بَعْدَ ذَلِكَ يَقُولُ زَعَمَ ‏ ‏ابْنُ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ ‏","","",""],[5068,5068,"","আমরা তার জন্য যা করেছে তার ব্যাপারে ভালো খবর নিয়ে কথা বলছিলাম। আমি সেই ছেলেটিকে শেষ করে দেবো যে বলেছিল এটা একটা কাজ যেটা সে তার মুখ থেকে বের হয়ে আসার পর থেকে তৃতীয়বার বের হয়ে আসে। আর আমি জানি যে, সে তার মুখের সামনে থেকে বের হয়ে এসেছে। আর আমি তাকে একটা ভাল খবর বের করতে চাই। আমি তাকে একটা কাজ শেষ করবো। আমি এই বিষয়ে বলতে চাই যে, আমি এই কাজ শেষ করতে চাই। আমি এই কাজটি শেষ করতে চাই। আমি এই প্রথম বার আমি শেষ করবো। আমি এই কাজটি শেষ করব। আমি তাকে বলেছিলাম, আমি জানি যে, আমি এই কাজটি শেষ করব। আমি জানি না। আমি জানি, আমি এটা একটা কাজ করবো। আমি জানি, আমি জানি না। আমি জানি, আমি এটা একটা কাজ করবো। আমি যা করব। আমি তোমার সাথে আছি। আমি যদি তুমি জানো না। আমি তোমার কথা বলি, আমি তোমার সামনে তোমার সাথে সাথে সাথে সাথে থাকবে। আমি তোমার মুখের সামনে তোমার মুখ থেকে কিছু একটা ছোট ছিলাম। আর আমি তোমার সাথে ছিলাম। আর আমি যদি তুমি জানো না। আমি তোমার সাথে কথা বলি, যখন সে আমার চাকরি কেটে দিল,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏نَافِعٌ ‏ ‏يُفَسِّرُهَا الثَّمَرَةُ ‏ ‏تُشْتَرَى ‏ ‏بِخَرْصِهَا ‏ ‏تَمْرًا بِكَيْلٍ مُسَمًّى إِنْ زَادَتْ فَلِي وَإِنْ نَقَصَتْ فَعَلَيَّ ‏","","",""],[5069,5069,"","ঈশ্বর তাকে ফিরে আসার আদেশ দিয়েছেন আর এরপর তিনি প্রতারণা করবেন । ( আদিপুস্তক ১: ২৭) এরপর তিনি তাকে হত্যা করতে পারেন । সে তোমাকে তোমার ক্রস আর মেয়েদের থেকে আদেশ দিয়েছে তোমার আর তার ছেলের।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَسَأَلَ ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ أَنْ يُرَاجِعَهَا ثُمَّ يُمْهِلَهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ ثُمَّ يُطَلِّقَهَا قَبْلَ أَنْ يَمَسَّهَا فَتِلْكَ الْعِدَّةُ الَّتِي أَمَرَ اللَّهُ أَنْ تُطَلَّقَ لَهَا النِّسَاءُ وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا سُئِلَ عَنْ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ وَهِيَ حَائِضٌ يَقُولُ إِمَّا أَنْتَ طَلَّقْتَهَا وَاحِدَةً أَوْ اثْنَتَيْنِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ أَنْ يُرَاجِعَهَا ثُمَّ يُمْهِلَهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ ثُمَّ يُطَلِّقَهَا إِنْ لَمْ يُرِدْ ‏ ‏إِمْسَاكَهَا ‏ ‏وَإِمَّا أَنْتَ طَلَّقْتَهَا ثَلَاثًا فَقَدْ عَصَيْتَ اللَّهَ تَعَالَى فِيمَا أَمَرَكَ بِهِ مِنْ طَلَاقِ امْرَأَتِكَ وَبَانَتْ مِنْكَ وَبِنْتَ مِنْهَا ‏","","",""],[5070,5070,"","আমরা একটা ছেলের জন্য অনুগ্রহ নিয়ে কথা বলেছি যে কিনা এই বদমাশটাকে আর আগুন বলে। ঈশ্বর তার মনে প্রবেশ করেছেন যে আমি যদি বলি ঈশ্বর আমাকে ফিরিয়ে দিতে হবে তাহলে আমি আর সেটিতে পারি না তার উপর হাঙ্গরের ঝোঁকে শয়তানী দিয়ে খেলতে হবে, ঈশ্বরের সাথে যুদ্ধ করতে হবে, আমি হয়তো ঈশ্বরের ইচ্ছাতে ছিলাম। আমি তাদের মধ্যে যা দেখেছি, তা কখনো দেখিনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏كَانَ لَا يَدَعُ الْحَجَّ وَالْعُمْرَةَ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏دَخَلَ عَلَيْهِ فَقَالَ إِنِّي لَا آمَنُ أَنْ يَكُونَ الْعَامَ بَيْنَ النَّاسِ قِتَالٌ فَلَوْ أَقَمْتَ فَقَالَ قَدْ ‏ ‏حَجَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَالَ كُفَّارُ ‏ ‏قُرَيْشٍ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏فَإِنْ يُحَلْ بَيْنِي وَبَيْنَهُ أَفْعَلْ كَمَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏ثُمَّ قَالَ أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ عُمْرَةً ثُمَّ سَارَ حَتَّى إِذَا كَانَ ‏ ‏بِالْبَيْدَاءِ ‏ ‏قَالَ ‏ ‏وَاللَّهِ مَا أَرَى سَبِيلَهُمَا إِلَّا وَاحِدًا أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ مَعَ عُمْرَتِي حَجًّا ثُمَّ طَافَ طَوَافًا وَاحِدًا ‏","","",""],[5071,5071,"","আমরা বলি যে, এটা শহরকে ধূমপায়ী ও দুর্ভোগের মাধ্যমে ধ্বংস করে দিয়েছে। আর তারা বলে আমি এটা করি। ঠিক শিক্ষা থেকে ডানদিকে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مِنْ أَيْنَ تَأْمُرُنَا أَنْ ‏ ‏نُهِلَّ ‏ ‏قَالَ ‏ ‏يُهِلُّ ‏ ‏أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَأَهْلُ ‏ ‏الشَّأَمِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَأَهْلُ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏قَالَ وَيَقُولُونَ وَأَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[5072,5072,"","আমরা একটা ছেলের জন্য আশীর্বাদ নিয়ে কথা বলেছি যে বলেছে যে সে বলেছে যে, ঈশ্বরের কাছে প্রার্থনা করতে, সে বলেছে আমরা কি খুন করেছি যদি আমরা জানোয়ারকে মেরে ফেলি, কনদোম আর নামার জন্য। ঘৃণা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا نَقْتُلُ مِنْ الدَّوَابِّ إِذَا أَحْرَمْنَا قَالَ ‏ ‏خَمْسٌ لَا جُنَاحَ عَلَى مَنْ قَتَلَهُنَّ فِي قَتْلِهِنَّ الْحِدَأَةُ وَالْغُرَابُ وَالْفَأْرَةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْعَقْرَبُ ‏","","",""],[5073,5073,"","আমরা একটা ছেলের জন্য কথা বলেছিলাম যে মানুষ, কখনো যেতে দেব না। বার্ন্সকে নিয়ে খেলা করা কাপড়ের ভেতর বা এমনকি কারো উপরও ঠিক না। দুইবার।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مَا نَلْبَسُ مِنْ الثِّيَابِ إِذَا أَحْرَمْنَا قَالَ ‏ ‏لَا تَلْبَسُوا الْقَمِيصَ وَلَا السَّرَاوِيلَ وَلَا الْعِمَامَةَ وَلَا الْخُفَّيْنِ إِلَّا أَحَدٌ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا ‏ ‏الْبُرْنُسَ ‏ ‏وَلَا شَيْئًا مِنْ الثِّيَابِ مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏أَوْ ‏ ‏زَعْفَرَانٌ ‏","","",""],[5074,5074,"","আমরা একজন দাসের কথা বলেছিলাম যিনি আমাকে একজন সাক্ষীর সাথে কথা বলেছিলেন যে ঈশ্বর তাকে বলেছেন, তিনি এই জিনিস থেকে মুক্তি দিবেন আর তার মানে হচ্ছে তার ড্রিংক করা।","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏ثُوَيْرٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا مِنْ هَذَا وَدَعُوا هَذَا ‏ ‏يَعْنِي شَارِبَهُ الْأَعْلَى يَأْخُذُ مِنْهُ ‏ ‏يَعْنِي ‏ ‏الْعَنْفَقَةَ ‏","","",""],[5075,5075,"","আমরা একজন মহান রক্ষকের সাথে কথা বলেছি যে তোমার সাথে এমন একজন কাঠবিড়ালীর দেখা করে। আমি আমার নিজের ভগবানের সাথে বসে আছি, তাই সে একটা হাঙ্গরের কাছে গিয়ে মারা গেল, যে তার পরে তাকে ডেকেছে। আমার ছেলে এমন একজন জিনিয়াস যে তোমাকে দোষারোপ করতে চায়, ঈশ্বর তাকে উদ্ধার করতে হবে আর আমি তাকে পাপ করব যে তাকে দেখতে এসেছে মে মাসের মে মাসে তাকে ভয় না পেতে। সে হবে জীবন-মরণ","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ يَنَّاقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فِي مَجْلِسِ ‏ ‏بَنِي عَبْدِ اللَّهِ ‏ ‏فَمَرَّ فَتًى مُسْبِلًا ‏ ‏إِزَارَهُ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَدَعَاهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَقَالَ مِمَّنْ أَنْتَ فَقَالَ مِنْ ‏ ‏بَنِي بَكْرٍ ‏ ‏فَقَالَ تُحِبُّ أَنْ يَنْظُرَ اللَّهُ تَعَالَى إِلَيْكَ يَوْمَ الْقِيَامَةِ قَالَ نَعَمْ قَالَ ارْفَعْ ‏ ‏إِزَارَكَ ‏ ‏فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْمَأَ بِإِصْبَعِهِ إِلَى أُذُنَيْهِ يَقُولُ ‏ ‏مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏لَا يُرِيدُ إِلَّا ‏ ‏الْخُيَلَاءَ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5076,5076,"","আমরা একজন দেবীর পুত্রের দেখা দেখার জন্য আমাদের জীবনের এক তৃতীয়াংশ গোপন বিষয় নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثُوَيْرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ ‏ ‏وَالْمُتَرَجِّلَاتِ ‏ ‏مِنْ النِّسَاءِ ‏","","",""],[5077,5077,"","ঈশ্বর আমাকে ক্ষমার অযোগ্যতার ফাঁদে পা দিয়েছেন । সে কাছে এসে স্নিচিং করছিল।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏وَكَانَ فِي النُّسْخَةِ الَّتِي قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏نَافِعٍ ‏ ‏فَغَيَّرَهُ فَقَالَ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5078,5078,"","আমরা একটা ভাল ছেলেকে খুঁজছি, তোমার টাকা বলে একটা ছেলের জন্য যে ঈশ্বরের কাছে পাঠানো হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5079,5079,"","তিনি বলেছিলেন, আমার কাছে তোমার টাকা ছিল, যাতে তিনি আমার বাবাকে বলেছিলেন এবং আমি তোমার স্বপ্ন থেকে আমাকে রক্ষা করার চেষ্টা করেছি । আমি বৃদ্ধ ছিলাম এবং আমি নরকে যাচ্ছি, অপমান এবং আমার কথা ছিল, যখন ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন। তিনি প্রভুর কাছে প্রার্থনা করবেন এবং তিনি তাঁর কাছে প্রার্থনা করবেন। ( লূক ১১: ১৩) এই ধরনের প্রার্থনা করা হয়তো তার নিজের মুখকে নিজের মুখে রাখতে পারত এবং নিজের মুখে মুখে বলতে পারত যে, তার এই কৌশলটা তার গোপন ছিল ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ الرَّحْمَنِ الْمُعَاوِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَآنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَأَنَا أَعْبَثُ بِالْحَصَى فِي الصَّلَاةِ فَلَمَّا انْصَرَفَ نَهَانِي وَقَالَ اصْنَعْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ قُلْتُ وَكَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ فِي الصَّلَاةِ وَضَعَ كَفَّهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى وَقَبَضَ أَصَابِعَهُ كُلَّهَا وَأَشَارَ بِإِصْبَعِهِ الَّتِي ‏ ‏تَلِي ‏ ‏الْإِبْهَامَ وَوَضَعَ كَفَّهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى ‏","","",""],[5080,5080,"","তিনি আমাকে ক্ষমার অযোগ্যতার বিষয়ে বলেছেন: ঈশ্বর ভুলে যাওয়ার পর আপনার টাকা দিয়ে আপনি এটা ভুলে যান। তিনি সমাজের প্রার্থনাকে তিনি রক্ষা করেন যাতে আপনি সেই সমস্ত লোকের প্রার্থনার উত্তর দেন, যারা আপনার বাহিনীর সাথে প্রার্থনা করতে চান। সাত আর দশ ডিগ্রি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ عَلَى صَلَاةِ ‏ ‏الْفَذِّ ‏ ‏بِسَبْعٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[5081,5081,"","আমরা আপনাদের সব থেকে ভালো কথা বলেছি খালিদ বেনের ছেলে থেকে পলাতকের ব্যাপারে আপনার টাকা দিয়ে আমরা বসলাম। আমরা কোরানে ভয় পাচ্ছি আর আমরা তারার আগমন দেখতে পাব। তার আত্মসমর্পণ করতে হবে আর আমরা কিছু করতে পারবো না যখন সে যা করেছে, তা সে করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ آلِ ‏ ‏خَالِدِ بْنِ أَسِيدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنَّا نَجِدُ صَلَاةَ الْخَوْفِ فِي الْقُرْآنِ وَصَلَاةَ الْحَضَرِ وَلَا نَجِدُ صَلَاةَ ‏ ‏السَّفَرِ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَعَالَى بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا نَعْلَمُ شَيْئًا فَإِنَّمَا نَفْعَلُ كَمَا رَأَيْنَا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ‏","","",""],[5082,5082,"","সে বলেছিল, আমি তোমাকে তোমার টাকা সম্পর্কে বলেছিলাম আর আমরা ঈশ্বরের ঋণের কথা বলেছিলাম, যখন তাকে বলা হয়েছিল যে, সে তার জন্য ঈশ্বরের কাছে প্রার্থনা করছে, তাকে তার অবতরণের অনুমতি দেয়া হয়েছে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ فِي السَّفَرِ حَيْثُمَا تَوَجَّهَتْ بِهِ ‏","","",""],[5083,5083,"","সে বলেছিল, তোমার টাকা আমাদের কাছে অনেক মূল্যবান ছিল যখন সে চলে গিয়েছিল, তাকে ঈশ্বরের কাছে প্রার্থনা করতে বলা হয়েছিল, আর সে তার গলায় থুতু মারতে দেখেছিল তার কাজ শেষ, আমি তাকে ঠিকানা দিতে কল করেছি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى بُصَاقًا فِي جِدَارِ الْقِبْلَةِ فَحَكَّهُ ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَبْصُقَنَّ قِبَلَ وَجْهِهِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قِبَلَ وَجْهِهِ إِذَا صَلَّى ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِي حَدِيثِهِ بُصَاقًا ‏","","",""],[5084,5084,"","সে আমাকে বলেছে, আমি ক্ষমার অযোগ্যতে পড়েছি: আপনার টাকা ঈশ্বরের দোহাইর উপর ভিত্তি করে ছিল, কিন্তু ঈশ্বর নিজেই তা করেছেন এবং তিনি এই পোশাক পরতে চান। ওয়ার্ডেন আর তারপর সে সেই ভয় পেয়ে যাবে যাকে ক্ষমা করা হবে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَ الْمُحْرِمُ ثَوْبًا مَصْبُوغًا ‏ ‏بِزَعْفَرَانٍ ‏ ‏أَوْ ‏ ‏وَرْسٍ ‏ ‏وَقَالَ مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَلْيَقْطَعْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[5085,5085,"","সে বলেছিল, আমরা ঝুঁকি সম্পর্কে পড়েছি: আপনার টাকা তৈরি করেছি... আমরা আপনার টাকা একটি শাস্তির কাছ থেকে পরিবর্তন করেছি. আমার বাবা বলেন যে, এটা ঈশ্বরের জন্য দোষ. তাকে উদ্ধার করতে হবে... ...এবং তার কোন মহিমা থাকবে না.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَيْدَاؤُكُمْ ‏ ‏هَذِهِ الَّتِي تَكْذِبُونَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏ ‏مَا ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مِنْ عِنْدِ ‏ ‏الْمَسْجِدِ ‏ ‏يَعْنِي ‏ ‏مَسْجِدَ ذِي الْحُلَيْفَةِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَقَدْ سَمِعْتُهُ مِنْ ‏ ‏مَالِكٍ ‏","","",""],[5086,5086,"","সে বলেছে আমরা তোমার টাকা ফেরত পেতে পারি। আর তারপরে আমি জানি যে ঈশ্বর তোমাকে পাশ করেছে। আমি তোমাকে খুঁজে বের করবো, তুমি কখনো ধরনি, তুমি কে, তুমি কখনো স্পর্শ করো না, তুমি দেখতে পাচ্ছ তুমি কে গরমে পরিণত হয়েছে আর তুমি দেখতে পাচ্ছ তুমি কিনা যারা এটা দেখেছে। লর্ড লর্ড অফ লর্ডের আঘাত। ঈশ্বর কখনো তাকে দেখেননি এবং প্রভুও নন। সঠিক কাজটি করাই ঈশ্বরের কাছে চাওয়া। এটা পড়াটা অনেক উজ্জ্বল এবং এটা হবে না। আমি তাকে করব, না হলে আমিই এটা করবো.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ جُرَيْجٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏رَأَيْتُكَ تَصْنَعُ أَرْبَعًا لَمْ أَرَ مِنْ أَصْحَابِكَ مَنْ يَصْنَعُهَا قَالَ مَا هُنَّ يَا ‏ ‏ابْنَ جُرَيْجٍ ‏ ‏قَالَ رَأَيْتُكَ لَا تَمَسُّ مِنْ الْأَرْكَانِ إِلَّا الْيَمَانِيَيْنِ وَرَأَيْتُكَ تَلْبَسُ النِّعَالَ ‏ ‏السِّبْتِيَّةَ ‏ ‏وَرَأَيْتُكَ تَصْبُغُ بِالصُّفْرَةِ وَرَأَيْتُكَ إِذَا كُنْتَ ‏ ‏بِمَكَّةَ ‏ ‏أَهَلَّ ‏ ‏النَّاسُ إِذَا رَأَوْا الْهِلَالَ وَلَمْ ‏ ‏تُهْلِلْ ‏ ‏أَنْتَ حَتَّى يَكُونَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَمَّا الْأَرْكَانُ فَإِنِّي ‏ ‏لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمَسُّ إِلَّا الْيَمَانِيَيْنِ وَأَمَّا النِّعَالُ ‏ ‏السِّبْتِيَّةُ ‏ ‏فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْبَسُ النِّعَالَ الَّتِي لَيْسَ فِيهَا شَعَرٌ وَيَتَوَضَّأُ فِيهَا فَأَنَا أُحِبُّ أَنْ أَلْبَسَهَا وَأَمَّا الصُّفْرَةُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْبُغُ بِهَا فَأَنَا أُحِبُّ أَنْ أَصْبُغَ بِهَا وَأَمَّا ‏ ‏الْإِهْلَالُ ‏ ‏فَإِنِّي لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ ‏ ‏حَتَّى ‏ ‏تَنْبَعِثَ ‏ ‏بِهِ نَاقَتُهُ ‏","","",""],[5087,5087,"","আমার ভালবাসার কারণে আমাকে সাহায্য করে দুইটা সাল্ম করেছি। ঈশ্বরের কাছে পাঠানো একটি ছেলের কথা, ঈশ্বর আদেশ দিয়েছেন তাকে সিংহাসনের বজ্রপাতে আত্মসমর্পণ করেছেন। প্রতিটি স্বাধীন বা বুদ্ধিসম্পন্ন মানুষ। পণ্ডিতদের কাছ থেকে শপথ বা নারী.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الْجُمَحِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَضَ زَكَاةَ الْفِطْرِ مِنْ رَمَضَانَ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ عَلَى كُلِّ حُرٍّ أَوْ عَبْدٍ ذَكَرٍ أَوْ أُنْثَى مِنْ الْمُسْلِمِينَ ‏","","",""],[5088,5088,"","আমি আমার ছেলেকে বলেছিলাম যে, তিনি তার সেরা গুলির মধ্যে দিয়ে যাচ্ছেন, যার মৃত্যু হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏خُسِفَ بِهِ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِي الْأَرْضِ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[5089,5089,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন । রাতভর প্রার্থনার জন্য তিনি বললেন, তুমি সকালে হাঁটু গেড়ে বসে কখনো তোমার জন্য না বলে থাকতে ভয় পেয়েছ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ صَلَاةِ اللَّيْلِ فَقَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى تُسَلِّمُ فِي كُلِّ رَكْعَتَيْنِ فَإِذَا خِفْتَ الصُّبْحَ فَصَلِّ رَكْعَةً ‏ ‏تُوتِرُ ‏ ‏لَكَ مَا قَبْلَهَا ‏","","",""],[5090,5090,"","আমি আমার স্বপ্নের ফুল সম্পর্কে কথা বলেছি, আমি আমার বাবার কাছে প্রার্থনা করেছি যে তিনি এখানে জড়িত না হয়ে যখন তিনি তার দায়িত্ব পালন করবেন, কিন্তু আমি তাকে বলছি, আর এটা ভ্রমণকারীদের নিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا مَرَّ ‏ ‏بِالْحِجْرِ ‏ ‏قَالَ ‏ ‏لَا تَدْخُلُوا مَسَاكِنَ الَّذِينَ ظَلَمُوا إِلَّا أَنْ تَكُونُوا بَاكِينَ أَنْ يُصِيبَكُمْ مَا أَصَابَهُمْ ‏ ‏وَتَقَنَّعَ ‏ ‏بِرِدَائِهِ وَهُوَ عَلَى ‏ ‏الرَّحْلِ ‏","","",""],[5091,5091,"","আমরা দুজন পরিচিত লোকের কথা বলেছি, আমরা একটি ছেলেকে কথা বলেছি এবং একবার ঈশ্বরের পুত্র সম্পর্কে বলেছি। পুত্র তার জন্য প্রার্থনা করেছে এবং আমি বলবো, \"আপনার দশ বছরের মেয়ে এসেছে।\" শিকার এবং আমি যে কোন সময়ের চেয়ে বেশী বিশ্বাস করতে চাই। \" আগুন কত বড় যন্ত্রণা এবং কিভাবে দশবার কাউকে পৃথিবীর হৃদয় থেকে বোকা বানানো হয়েছে তা কখনো দেখা যায়নি। মানুষ বলে আমরা পিতা-মাতার মন কেটে ফেলি, যে কিনা মৃত্যুর সাক্ষী হতে পারে, সে হচ্ছে সেই ব্যক্তি যে কিনা এক ব্যক্তি। যে ই এই জন ্ য একমাত্র সেই-ই বা কে সেই সেই যার প ্ রতি তিনি ঈমান এনেছে , আর তিনিই হলেন সেই ব্যক্তি যিনি এক সম ্ পর ্ কে -- যে ই এই জন ্ য একমাত্র সেই-ই বা কে সেই সেই যার প ্ রতি তিনি ঈমান এনেছে , আর তিনিই হলেন সেই ব্যক্তি যিনি এক সম ্ পর ্ কে -- যে ই এই জন ্ য একমাত্র সেই-ই বা কে সেই সেই যার প ্ রতি তিনি ঈমান এনেছে , আর তিনিই হলেন সেই ব্যক্তি যিনি এক সম ্ পর ্ কে -- যে ই সেই ব্যক্তি যিনি এই ব্যক্তি যিনি সেই সেই সেই সেই ব্যক্তি যিনি... তুমি প্রার্থনা করো এবং তোমার আগে ভোজ কর, তাই আমরা ঋণ কেটে ফেলি।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏وَقَالَ مَرَّةً ‏ ‏حَيْوَةُ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏تَصَدَّقْنَ ‏ ‏وَأَكْثِرْنَ فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ لِكَثْرَةِ اللَّعْنِ وَكُفْرِ ‏ ‏الْعَشِيرِ ‏ ‏مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَغْلَبَ لِذِي ‏ ‏لُبٍّ ‏ ‏مِنْكُنَّ قَالَتْ يَا رَسُولَ اللَّهِ وَمَا نُقْصَانُ الْعَقْلِ وَالدِّينِ قَالَ أَمَّا نُقْصَانُ الْعَقْلِ وَالدِّينِ فَشَهَادَةُ امْرَأَتَيْنِ تَعْدِلُ شَهَادَةَ رَجُلٍ فَهَذَا نُقْصَانُ الْعَقْلِ وَتَمْكُثُ ‏ ‏اللَّيَالِيَ لَا تُصَلِّي وَتُفْطِرُ فِي رَمَضَانَ فَهَذَا نُقْصَانُ الدِّينِ ‏","","",""],[5092,5092,"","আমরা কথা বলেছি, ঈশ্বর আমাদের বলেছেন, তিনি যেন তাঁর ছেলের জন্য তাকে শাস্তি দেন। ঈশ্বর হচ্ছেন প্রভু প্রভুর পক্ষ থেকে উত্তম বিষয় প্রদান করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى الْيَدُ الْعُلْيَا الْمُنْفِقَةُ وَالْيَدُ السُّفْلَى السَّائِلَةُ ‏","","",""],[5093,5093,"","ঈশ্বর আমাদের বলেছেন, আমরা একটি ছেলের জন্য নাম গোপন করেছি যাকে মৃত্যুদণ্ড দেয়া হয়েছে। ঈশ্বর আদেশ দিয়েছেন, আমি মানুষের মুক্তির আগেই তার তেল পাস করবো। প্রার্থনা করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِزَكَاةِ الْفِطْرِ أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلَاةِ ‏","","",""],[5094,5094,"","আমরা আমাদের সর্বোচ্চ আল্লাহকে বলেছি যে তিনি ঈশ্বরের এক বিশ্বকে শাস্তি দেবেন। আল্লাহ তাঁর কাছে প্রার্থনা করেছেন এবং ঈশ্বরের কাছে প্রার্থনা করেছেন। তিনি বলেছেন, তিনি এত কঠোর। ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَالَ فِيهِ قَوْلًا شَدِيدًا ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنَا ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَكْثَرُ مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْلِفُ بِهَذِهِ الْيَمِينِ يَقُولُ لَا وَمُقَلِّبِ الْقُلُوبِ ‏","","",""],[5095,5095,"","আমরা লর্ড লর্ড লর্ডের লর্ডশিপের কথা বলেছি, যে ছেলে তার বাবা হতে ভুলে গেছে, সে ইতিমধ্যে তাদের চারপাশে ঘুরে বেড়াচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبَّقَ بِالْخَيْلِ وَرَاهَنَ ‏","","",""],[5096,5096,"","আমরা আমাদের বাবার আবেগ নিয়ে কথা বলেছি, বাবার ছেলের মায়ের প্রতি বিশ্বাস রাখার জন্য চিনি। ঈশ্বরের সাথে ঝগড়া বন্ধ করতে হবে তার দশ বছরের বাচ্চার মধ্যে। প্রার্থনা হচ্ছে, পড়া।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَمْزَةَ يَعْنِي السُّكَّرِيَّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏صَدَقَةَ الْمَكِّيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏اعْتَكَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ فَاتُّخِذَ لَهُ فِيهِ بَيْتٌ مِنْ ‏ ‏سَعَفٍ ‏ ‏قَالَ فَأَخْرَجَ رَأْسَهُ ذَاتَ يَوْمٍ فَقَالَ ‏ ‏إِنَّ الْمُصَلِّيَ يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ فَلْيَنْظُرْ أَحَدُكُمْ بِمَا يُنَاجِي رَبَّهُ وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقِرَاءَةِ ‏","","",""],[5097,5097,"","আমরা কথা বলেছি কিভাবে আমি একটি ছেলে হতে পছন্দ করতাম, সে তার কাছে প্রার্থনা করলো আর সে তার মাস্টারকে পাঠিয়ে দিল যে তার আলবিকে বেছে নিয়েছিল আর তাকে কষ্ট দিত।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ الْحَرَّانِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏الدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَرَنَ بَيْنَ حَجَّتِهِ وَعُمْرَتِهِ أَجْزَأَهُ لَهُمَا طَوَافٌ وَاحِدٌ ‏","","",""],[5098,5098,"","ঈশ্বর বলেছিলেন যে, মুঘেতের একটা শাস্তি ছিল । ভাই আমার সাথে কথা বলতে না পেরে আমার সাথে ঘোড়ায় চড়েন। তাকে যখন বলা হয়েছিল মাউসের দিকে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَرَّ ثَوْبَهُ ‏ ‏خُيَلَاءَ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏إِنَّ أَحَدَ شِقَّيْ ثَوْبِي يَسْتَرْخِي إِلَّا أَنْ أَتَعَاهَدَ ذَلِكَ مِنْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ لَسْتَ مِمَّنْ يَصْنَعُ ذَلِكَ خُيَلَاءَ ‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏قُلْتُ ‏ ‏لِسَالِمٍ ‏ ‏أَذَكَرَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏قَالَ لَمْ أَسْمَعْهُ ذَكَرَ إِلَّا ثَوْبَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏فَذَكَرَ مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[5099,5099,"","আমরা রাজার টোপের উপর নজর রাখার চেষ্টা করেছি, এক ছেলে ঈশ্বরকে বলতে চাই যে, তাকে এই দু:খের মধ্যে ফেলে দেয়া হবে। আমি এমন একজনের চেয়ে বেশি কিছু। এটা পাথর বা গাছকে স্পর্শ করার জন্য একে একে আঘাত করবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْزِلُ ‏ ‏الدَّجَّالُ ‏ ‏فِي هَذِهِ ‏ ‏السَّبَخَةِ ‏ ‏بِمَرِّقَنَاةَ ‏ ‏فَيَكُونُ أَكْثَرَ مَنْ يَخْرُجُ إِلَيْهِ النِّسَاءُ حَتَّى إِنَّ الرَّجُلَ لَيَرْجِعُ إِلَى حَمِيمِهِ وَإِلَى أُمِّهِ وَابْنَتِهِ وَأُخْتِهِ وَعَمَّتِهِ فَيُوثِقُهَا رِبَاطًا مَخَافَةَ أَنْ تَخْرُجَ إِلَيْهِ ثُمَّ يُسَلِّطُ اللَّهُ الْمُسْلِمِينَ عَلَيْهِ فَيَقْتُلُونَهُ وَيَقْتُلُونَ شِيعَتَهُ حَتَّى إِنَّ الْيَهُودِيَّ لَيَخْتَبِئُ تَحْتَ الشَّجَرَةِ أَوْ الْحَجَرِ فَيَقُولُ الْحَجَرُ أَوْ الشَّجَرَةُ لِلْمُسْلِمِ هَذَا يَهُودِيٌّ تَحْتِي فَاقْتُلْهُ ‏","","",""],[5100,5100,"","আমরা আপনার রাজার মন বাঁচাতে চেষ্টা করেছি আমাদের কাছে কত বার আমরা একটি ছেলে খুঁজছি। নবী তার জন্য প্রার্থনা করেছেন এবং তার ক্ষমা প্রার্থনা করবেন এক শতের জন্য আর তারপর বলবে, লর্ড আমার কাছে ক্ষমা এসেছে, তুমি একজন ভালো খেলা, নাকি তুমি রহস্যের খেলা।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏أَخْبَرَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ اسْتَغْفَرَ مِائَةَ مَرَّةٍ ثُمَّ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ‏ ‏أَوْ إِنَّكَ تَوَّابٌ غَفُورٌ ‏","","",""],[5101,5101,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং শহরের অতীতের দিকে অক্সিজেন সরবরাহ করেছেন, ওর পাপ আর মৃত্যুর পর্দা, সেই ছেলেটা থেকে আমি সমাধান করতে ক্লান্ত।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏قَالَ وَقَالَ ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَوْثَرُ نَهَرٌ فِي الْجَنَّةِ حَافَّتَاهُ مِنْ ذَهَبٍ وَالْمَاءُ يَجْرِي عَلَى اللُّؤْلُؤِ وَمَاؤُهُ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ ‏","","",""],[5102,5102,"","আমরা তাকে এটা করতে বলেছিলাম, সে মাথায় সম্পূর্ণ পাগলের মত কাজ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقَزَعِ ‏ ‏فِي الرَّأْسِ ‏","","",""],[5103,5103,"","আমরা মূসা কথা বলেছি যখন আমার বাবা মারা যান, ঈশ্বর তাকে শিখিয়েছিলেন আর তিনি বলেছিলেন যে তার ভাইয়ের শান্তি যেন না নেয় আর বলে যে তুমি মরবে তিনি যদি সন্তুষ্ট থাকেন এবং তার কাজের জন্য তাকে ফিরে যেতে দেন, তাহলে তিনি ফিরে আসেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ وَيَقُولُ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ مَا تَوَادَّ اثْنَانِ فَفُرِّقَ بَيْنَهُمَا إِلَّا بِذَنْبٍ يُحْدِثُهُ أَحَدُهُمَا وَكَانَ يَقُولُ لِلْمَرْءِ الْمُسْلِمِ عَلَى أَخِيهِ مِنْ الْمَعْرُوفِ سِتٌّ يُشَمِّتُهُ إِذَا عَطَسَ وَيَعُودُهُ إِذَا مَرِضَ وَيَنْصَحُهُ إِذَا غَابَ وَيَشْهَدُهُ وَيُسَلِّمُ عَلَيْهِ إِذَا لَقِيَهُ وَيُجِيبُهُ إِذَا دَعَاهُ وَيَتْبَعُهُ إِذَا مَاتَ وَنَهَى عَنْ هِجْرَةِ الْمُسْلِمِ أَخَاهُ فَوْقَ ثَلَاثٍ ‏","","",""],[5104,5104,"","তিনি আমার মসজিদে একটা প্রার্থনা করতে চান, যাতে আমিও প্রার্থনা করতে পারি । সাগর খুঁজে বের করে","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[5105,5105,"","ঈশ্বর হয়তো আমার বাবা বলেছিলেন যে, ঈশ্বর ঈশ্বরের কাছে এসে তাঁর কাছে এসে এই কথা বলেছিলেন এবং তিনি সেই পুত্রের মতো আত্মসমর্পণ করেছেন । ঈশ্বর যেতে পেরে খুব ভালো আছেন এবং চলে যেতে পেরে চলে যান । সে এটা শুনে ফেলেছে.","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏الْهُذَيْلُ بْنُ بِلَالٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ جَلَسَ ذَاتَ يَوْمٍ ‏ ‏بِمَكَّةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏مَعَهُ فَقَالَ أَبِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏مَثَلَ الْمُنَافِقِ يَوْمَ الْقِيَامَةِ كَالشَّاةِ بَيْنَ ‏ ‏الرَّبِيضَيْنِ ‏ ‏مِنْ الْغَنَمِ إِنْ أَتَتْ هَؤُلَاءِ نَطَحْنَهَا وَإِنْ أَتَتْ هَؤُلَاءِ نَطَحْنَهَا فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَذَبْتَ فَأَثْنَى الْقَوْمُ عَلَى أَبِي خَيْرًا أَوْ مَعْرُوفًا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا أَظُنُّ صَاحِبَكُمْ إِلَّا كَمَا تَقُولُونَ وَلَكِنِّي شَاهِدٌ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ قَالَ كَالشَّاةِ بَيْنَ الْغَنَمَيْنِ فَقَالَ هُوَ سَوَاءٌ فَقَالَ هَكَذَا سَمِعْتُهُ ‏","","",""],[5106,5106,"","আমরা আমাকে হত্যা করার কথা বলেছিলাম কিন্তু আপনার বুকে আছে... ...আর বলা হয়েছে যে শুধুমাত্র ঈশ্বরের দয়া তার হাতে গুলি করা হয়েছে আর তাকে বলতে চাই যে আমি ভালোবাসা করি না। ঈশ্বর আমাদের এই কথাগুলো শেখাতে হবে... ...যেটা আমার বাবা সবচেয়ে ভাল জানেন.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ بَابَيْ الْمَكِّيُّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ إِلَى جَنْبِ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ فَلَمَّا قَضَى الصَّلَاةَ ضَرَبَ بِيَدِهِ عَلَى فَخِذِهِ فَقَالَ ‏ ‏أَلَا أُعَلِّمُكَ تَحِيَّةَ الصَّلَاةِ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا فَتَلَا عَلَيَّ هَؤُلَاءِ الْكَلِمَاتِ ‏ ‏يَعْنِي قَوْلَ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏فِي التَّشَهُّدِ ‏","","",""],[5107,5107,"","আমরা একটা বাপ্তিস্মের অর্থ ছিল একজন ছেলে, যিনি আমাদের ঈশ্বরের সঙ্গে সম্পর্ক রাখার বিষয়ে বলেছিলেন । আল্লাহ বলে সে একটা ছেলে থেকে শুনেনি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ فَعَلْتَ كَذَا وَكَذَا قَالَ لَا وَالَّذِي لَا إِلَهَ إِلَّا هُوَ مَا فَعَلْتُ قَالَ فَقَالَ لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَدْ فَعَلَ وَلَكِنْ قَدْ ‏ ‏غُفِرَ لَهُ بِقَوْلِ لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏لَمْ يَسْمَعْ هَذَا مِنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏بَيْنَهُمَا رَجُلٌ ‏ ‏يَعْنِي ‏ ‏ثَابِتًا ‏","","",""],[5108,5108,"","তিনি বলেছিলেন যে, ঈশ্বর যদি এমন কিছু বলতেন, যা আপনার কাছে এত ভাল হতো, তাহলে হামাদ বান সেলমাকে কথা বলতে হতো যে আমার প্রভু ও প্রভুর জন্য কাজ করে, তার জন্য আমি কৃতজ্ঞ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا حَلَفَ الرَّجُلُ فَقَالَ إِنْ شَاءَ اللَّهُ فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏إِنْ شَاءَ فَلْيَمْضِ وَإِنْ شَاءَ فَلْيَتْرُكْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَعَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5109,5109,"","আমরা কতবার এসব করেছি, ঈশ্বরের দোহাই, যখন ভূমি ঈশ্বরের কাছে প্রার্থনা করেছে যার কাছে তিনি কখনও জন্ম দেননি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنِي ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَبِشْرُ بْنُ عَائِذٍ الْهُذَلِيُّ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[5110,5110,"","কীভাবে তা এড়িয়ে চলতে হবে, তা জানা তুমি যা করতে পারো তা খুঁজে পাও নি, এমনকি তারা জানতেও পারবে, তুমি না জানলেও।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اسْتَعَاذَ بِاللَّهِ فَأَعِيذُوهُ وَمَنْ سَأَلَكُمْ بِاللَّهِ فَأَعْطُوهُ وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ وَمَنْ أَتَى إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ فَإِنْ لَمْ تَجِدُوا مَا تُكَافِئُوهُ فَادْعُوا لَهُ حَتَّى تَعْلَمُوا أَنْ قَدْ كَافَأْتُمُوهُ ‏","","",""],[5111,5111,"","বাবা আমার সাথে কথা বলে একটা ছেলের জন্য কাজ করার কথা বলেছিলাম যে সে আমাকে ভালবাসবে। সে একটা আংটি দিত আর সে তার মুখ একটা শেল্টার মধ্যে দিয়ে দিত। তার মন হারিয়ে গিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمٌ مِنْ ذَهَبٍ وَكَانَ ‏ ‏يَجْعَلُ فَصَّهُ فِي بَاطِنِ يَدِهِ قَالَ فَطَرَحَهُ ذَاتَ يَوْمٍ فَطَرَحَ النَّاسُ خَوَاتِيمَهُمْ ثُمَّ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ فَكَانَ يَخْتِمُ بِهِ وَلَا يَلْبَسُهُ ‏","","",""],[5112,5112,"","আমরা একটা বাপ্তিস্মের কথা বলেছিলাম কিন্তু একটা ছেলের জন্য কি মূল্য আছে যে ভালো ছিল, সে ফোন করে উত্তর দেয়,","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَجِيبُوا الدَّعْوَةَ إِذَا دُعِيتُمْ ‏","","",""],[5113,5113,"","আমরা আমাদের সময় নিয়ে কথা বলেছিলাম আর তাকে ঈশ্বরের অনুগ্রহে শাস্তি দেয়া হয়, আর সে সেই শপথটা করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏يَمِينُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّتِي يَحْلِفُ بِهَا لَا وَمُقَلِّبِ الْقُلُوبِ ‏","","",""],[5114,5114,"","আমরা আমাদের আলোচনা সম্পর্কে কথা বলেছি এবং তিনি আমাকে এটা শোনার চেষ্টা করে আমাদের সাথে কাজ করেছেন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার আত্মার কাছে আত্মসমর্পণ করবেন। ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমি প্রভুকে সমর্পণ করবো। তারপর তিনি বলেছিলেন, যদি সে করে থাকে তবে আমি কি করব না। উদ্ধার","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ لَقِيَ ‏ ‏زَيْدَ بْنَ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏بِأَسْفَلِ ‏ ‏بَلْدَحَ ‏ ‏وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَحْيُ فَقَدَّمَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُفْرَةً فِيهَا لَحْمٌ فَأَبَى أَنْ يَأْكُلَ مِنْهَا ثُمَّ قَالَ ‏ ‏إِنِّي لَا آكُلُ مَا تَذْبَحُونَ عَلَى أَنْصَابِكُمْ وَلَا آكُلُ إِلَّا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ حَدَّثَ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5115,5115,"","আমার ভাইয়ের ছেলের কথা বলেছিলাম, যিনি আমার লেখকের ব্যাপারে কিছু বলেছিলেন, ঈশ্বরের প্রার্থনা তার কাছে করবে আর তারা তোমার কাছে অতীতে এবং প্রভুর কাছে আত্মসমর্পণ করবে। আত্মসমর্পণ করা হয়েছে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فِي كِتَابِي ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وَضَعْتُمْ مَوْتَاكُمْ فِي الْقَبْرِ فَقُولُوا بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5116,5116,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন যেন তিনি তাঁর এই কথা বলার মাধ্যমে তাঁর কাছে প্রার্থনা করেন যে, তিনি তাঁর ভুলগুলোকে স্বীকার করেছেন । তার আদালতে প্রবেশের জন্য তাকে ক্ষমা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَارِثِ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَقِيتَ الْحَاجَّ فَسَلِّمْ عَلَيْهِ وَصَافِحْهُ وَمُرْهُ أَنْ يَسْتَغْفِرَ لَكَ قَبْلَ أَنْ يَدْخُلَ بَيْتَهُ فَإِنَّهُ مَغْفُورٌ لَهُ ‏","","",""],[5117,5117,"","আমরা আমার বাবাকে হত্যা করার চেষ্টা করেছি... ...একটা ছেলের জন্মের জন্য... ...আর সেই মহান স্থানে যাওয়ার জন্য, ঈশ্বর আমাকে আশীর্বাদ করুন যখন তিনি আমাকে বললেন তিনি করেছেন, তিনি যা করেছেন, তারা এই অপরাধীর জন্য... ...আর অন্ধ আর বিনয়ীর সিদ্ধান্ত নেবে এই কৌশলটা করতে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏قَطَنِ بْنِ وَهْبِ بْنِ عُوَيْمِرِ بْنِ الْأَجْدَعِ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ قَدْ حَرَّمَ اللَّهُ عَلَيْهِمْ الْجَنَّةَ مُدْمِنُ الْخَمْرِ ‏ ‏وَالْعَاقُّ ‏ ‏وَالدَّيُّوثُ ‏ ‏الَّذِي ‏ ‏يُقِرُّ ‏ ‏فِي أَهْلِهِ ‏ ‏الْخَبَثَ ‏","","",""],[5118,5118,"","ঈশ্বর সেই লোকেদের ধ্বংস করে দিয়েছেন, যারা আমাদের কাছ থেকে ছুঁড়ে ফেলে চলে গিয়েছে । কথা বলা হয়ে গেছে আর আমি বলতে চাচ্ছি আপনারা সবাই আশীর্বাদ করেছেন, যদি আমরা নিজ থেকে বের হয়ে আসি তাহলে আমরা ঈশ্বরকে খুঁজে বের করব। ভগবান তার কাছে প্রার্থনা করুন, আর আমরা আত্মসমর্পণ করব, কে এখানে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏لَقِيَ نَاسًا خَرَجُوا مِنْ عِنْدِ ‏ ‏مَرْوَانَ ‏ ‏فَقَالَ مِنْ أَيْنَ جَاءَ هَؤُلَاءِ قَالُوا خَرَجْنَا مِنْ عِنْدِ الْأَمِيرِ ‏ ‏مَرْوَانَ ‏ ‏قَالَ وَكُلُّ حَقٍّ رَأَيْتُمُوهُ تَكَلَّمْتُمْ بِهِ وَأَعَنْتُمْ عَلَيْهِ وَكُلُّ مُنْكَرٍ رَأَيْتُمُوهُ أَنْكَرْتُمُوهُ وَرَدَدْتُمُوهُ عَلَيْهِ قَالُوا لَا وَاللَّهِ بَلْ يَقُولُ مَا يُنْكَرُ فَنَقُولُ قَدْ أَصَبْتَ أَصْلَحَكَ اللَّهُ فَإِذَا خَرَجْنَا مِنْ عِنْدِهِ قُلْنَا قَاتَلَهُ اللَّهُ مَا أَظْلَمَهُ وَأَفْجَرَهُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏كُنَّا بِعَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعُدُّ هَذَا نِفَاقًا لِمَنْ كَانَ هَكَذَا ‏","","",""],[5119,5119,"","আমরা আমার বাবার কথা বলেছিলাম যে এটা করার পর তিনি ঈশ্বরের অনুগ্রহ লাভ করেছেন এবং তিনি তার করা পাপ তিনি আমাকে দিয়েছেন, আমি ভয় পাচ্ছি আমাকে আমার কাছে নিয়ে আসা হচ্ছে। আমার ছেলেরা আমরা ভুলে গিয়েছিলাম যে তুমি আমার বাড়িতে ধরা খেয়েছ, আর আমি চলে এসেছি। আর তাকে নিয়ে গেল.","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَعْطَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏جَارِيَةً ‏ ‏مِنْ ‏ ‏سَبْيِ ‏ ‏هَوَازِنَ ‏ ‏فَوَهَبَهَا لِي فَبَعَثْتُ بِهَا إِلَى أَخْوَالِي مِنْ ‏ ‏بَنِي جُمَحٍ ‏ ‏لِيُصْلِحُوا لِي مِنْهَا حَتَّى أَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏ثُمَّ أَاتِيَهُمْ وَأَنَا أُرِيدُ أَنْ أُصِيبَهَا إِذَا رَجَعْتُ إِلَيْهَا قَالَ فَخَرَجْتُ مِنْ الْمَسْجِدِ حِينَ فَرَغْتُ فَإِذَا النَّاسُ يَشْتَدُّونَ فَقُلْتُ مَا شَأْنُكُمْ قَالُوا ‏ ‏رَدَّ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْنَاءَنَا وَنِسَاءَنَا قَالَ قُلْتُ تِلْكَ صَاحِبَتُكُمْ فِي ‏ ‏بَنِي جُمَحٍ ‏ ‏فَاذْهَبُوا فَخُذُوهَا فَذَهَبُوا فَأَخَذُوهَا ‏","","",""],[5120,5120,"","আমরা সবাই মিলে একটা নির্দিষ্ট জীবনের পর একটা দৃশ্যের কথা বলেছি, ঈশ্বর আমাকে আমার আনন্দের আশীর্বাদ করেছেন। যদি তিনি আমাকে বলেন, আমি তা না করতাম। তোমার সাথে এটা করতে হবে, সে তোমাকে খুন করতে পেরে খুশি হয়েছে। একবার বলেছিল, যে কিনা তোমাকে খুন করেছে, বাবা, যখন সে ঈশ্বরে বিশ্বাস করে, আমি কিছুই করবো না। যদি তুমি ঈশ্বরের সাথে খেলতে চেষ্টা করো, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাকে ঈশ্বরের দোহাই দিয়ে উদ্ধার করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏جَلَسْتُ أَنَا ‏ ‏وَمُحَمَّدٌ الْكِنْدِيُّ ‏ ‏إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏ثُمَّ قُمْتُ مِنْ عِنْدِهِ فَجَلَسْتُ إِلَى ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ فَجَاءَ صَاحِبِي وَقَدْ اصْفَرَّ وَجْهُهُ وَتَغَيَّرَ لَوْنُهُ فَقَالَ قُمْ إِلَيَّ قُلْتُ أَلَمْ أَكُنْ جَالِسًا مَعَكَ السَّاعَةَ فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏قُمْ إِلَى صَاحِبِكَ قَالَ فَقُمْتُ إِلَيْهِ فَقَالَ أَلَمْ تَسْمَعْ إِلَى مَا قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏قُلْتُ وَمَا قَالَ قَالَ أَتَاهُ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَعَلَيَّ جُنَاحٌ أَنْ أَحْلِفَ ‏ ‏بِالْكَعْبَةِ ‏ ‏قَالَ وَلِمَ تَحْلِفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏إِذَا حَلَفْتَ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَاحْلِفْ بِرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فَإِنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ إِذَا حَلَفَ قَالَ كَلَّا وَأَبِي فَحَلَفَ بِهَا يَوْمًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحْلِفْ بِأَبِيكَ وَلَا بِغَيْرِ اللَّهِ فَإِنَّهُ مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ أَشْرَكَ ‏","","",""],[5121,5121,"","ঈশ্বর একটা ছেলেকে দিয়ে তার জন্য প্রার্থনা করেছেন, তার নিজের জন্য প্রার্থনা করার জন্য, আর তুমি তার আগে মারা গিয়েছিলে। মূল্যবোধকে মানুষ ধূমপায়ী হতে হতো... ...আমাদের বলা হত প্রভু, তোমার কথা।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَخْرُجُ نَارٌ مِنْ ‏ ‏حَضْرَمَوْتَ ‏ ‏أَوْ مِنْ بَحْرِ ‏ ‏حَضْرَمَوْتَ ‏ ‏قَبْلَ يَوْمِ الْقِيَامَةِ تَحْشُرُ النَّاسَ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ فَمَاذَا تَأْمُرُنَا قَالَ عَلَيْكُمْ ‏ ‏بِالشَّأَمِ ‏","","",""],[5122,5122,"","আমরা আমাদের চেয়ে ভালো একটা ছেলেকে নিয়ে কথা বলেছি, যে বলে ভগবানের পাপের জন্য প্রার্থনা করেছে, আত্মসমর্পণ করবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ ثَوْبَانَ ‏ ‏مَوْلَى ‏ ‏بَنِي زُهْرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏خُيَلَاءَ ‏","","",""],[5123,5123,"","আমরা সবাই একটা মুসার পুত্র হয়ে গেছি... ...আমাদের সাথে যুদ্ধরত ঘোড়ার দেখা হয়েছে... ...তার একটা দেবীর ছেলে আছে. ফাংশন.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ حُجْرَةِ ‏ ‏عَائِشَةَ ‏ ‏يَقُولُ ‏ ‏يُنْصَبُ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ وَلَا ‏ ‏غَدْرَةَ ‏ ‏أَعْظَمُ مِنْ ‏ ‏غَدْرَةِ ‏ ‏إِمَامِ عَامَّةٍ ‏","","",""],[5124,5124,"","আমরা আমার বাবাকে একটা ছেলের জন্য ভালবাসা দিতে বলেছিলাম, লর্ড ঈশ্বরকে তার শান্তি দিতে বলেছে, সমাধান করতে তার কোন বড় বিল্ডিং ছিল না। আপনি হয়তো তা করেছেন। আপনি তো জানেন না। আপনি কি জানেন? তোমার আত্মা যা করেছে তার জন্য ক্ষমা প্রার্থনা করো, আমার ছেলে তাকে তার কথা বলতে আদেশ দিয়েছে। সে বলবে, তুমি হয়তো এটা করতে পারো কিন্তু আল্লাহ্ মাফ করেছেন। তুমি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُدَّعِيَ ‏ ‏الْبَيِّنَةَ ‏ ‏فَلَمْ يَكُنْ لَهُ ‏ ‏بَيِّنَةٌ ‏ ‏فَاسْتَحْلَفَ الْمَطْلُوبَ فَحَلَفَ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ قَدْ فَعَلْتَ وَلَكِنْ ‏ ‏غُفِرَ لَكَ بِإِخْلَاصِكَ قَوْلَ لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ إِلَّا أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّكَ قَدْ فَعَلْتَ وَلَكِنَّ اللَّهَ غَفَرَ لَكَ ‏","","",""],[5125,5125,"","আমাদের কথা বলা উচিত, আমাদের কথা বলা উচিত, চেষ্টা করা উচিত, আমাদের উচিত, আমরা এমন একজন লোক আছে যে বলে তার কাছে সেরা। আপনি বলেছেন আদালতে যুদ্ধ করার সময় তারা আপনাকে হত্যা করছিল, হয় তাদের ঋণের কারণে অথবা তাদের ঋণের কারণে নয় বরং নিজের জীবন ধ্বংস করে না ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏بَيَانٍ ‏ ‏عَنْ ‏ ‏وَبَرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَنَحْنُ نَرْجُو أَنْ يُحَدِّثَنَا حَدِيثًا ‏ ‏أَوْ حَدِيثًا حَسَنًا ‏ ‏فَبَدَرَنَا رَجُلٌ مِنَّا يُقَالُ لَهُ ‏ ‏الْحَكَمُ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا تَقُولُ فِي الْقِتَالِ فِي ‏ ‏الْفِتْنَةِ ‏ ‏قَالَ ‏ ‏ثَكِلَتْكَ ‏ ‏أُمُّكَ وَهَلْ تَدْرِي مَا ‏ ‏الْفِتْنَةُ ‏ ‏إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَاتِلُ الْمُشْرِكِينَ فَكَانَ الدُّخُولُ فِيهِمْ أَوْ فِي دِينِهِمْ ‏ ‏فِتْنَةً ‏ ‏وَلَيْسَ كَقِتَالِكُمْ عَلَى الْمُلْكِ ‏","","",""],[5126,5126,"","আমরা আমার বাবার সাথে কথা বলেছি, যে তার জন্য প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ فَقَالَتْ إِنِّي قَدْ ‏ ‏أَحْدَثْتُ ‏ ‏فَقَالَ ‏ ‏أَوَحَيْضَتُكِ فِي يَدِكِ ‏","","",""],[5127,5127,"","আমরা আমার বাবা-এর কথা বলেছি যাতে সে এটা নিশ্চিত করতে পারে যে সে কি করেছে। ঈশ্বর তাকে জিজ্ঞেস করেছেন, সে নাকি এক ছেলের জন্য বেঁচে আছে। ঈশ্বরের অনুগ্রহে পাস, তিন সেকেন্ডের মধ্যে, অথবা যে তার সাথে দেখা করতে এসেছিল,","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ كَمْ اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَرَّتَيْنِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَقَدْ عَلِمَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏اعْتَمَرَ ثَلَاثَةً سِوَى الْعُمْرَةِ الَّتِي ‏ ‏قَرَنَهَا ‏ ‏بِحَجَّةِ الْوَدَاعِ ‏","","",""],[5128,5128,"","আমরা সবাই ভালো কাজ করেছি, আমরা সুখী, এবং আমার বাবার চেয়ে ভাল করেছি। আমি স্যারার ইচ্ছার কাছে গোপন ছিলাম তিনি আত্মসমর্পণ করেছেন এবং আত্মসমর্পণ করেছেন আমরা বলেছিলাম, আমরা কিভাবে এটা তৈরি করেছি, আমরা হয়ত কাপড় থেকে পালাবো আর তারপর আমরা রেগে যাবো আর তারপর বলেছিলাম আমরা ভিতরে গেলে ঈশ্বর যেন প্রার্থনা আর প্রার্থনা করতে পারেন। সে বলেছিল আমরা ব্রেক-আপ করতে যাচ্ছি। আর বলেছি আমরা যেন একে অপরের হাত ধরে চুমু খেতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي ‏ ‏سَرِيَّةٍ ‏ ‏مِنْ ‏ ‏سَرَايَا ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَاصَ ‏ ‏النَّاسُ ‏ ‏حَيْصَةً ‏ ‏وَكُنْتُ فِيمَنْ ‏ ‏حَاصَ ‏ ‏فَقُلْنَا كَيْفَ نَصْنَعُ وَقَدْ فَرَرْنَا مِنْ ‏ ‏الزَّحْفِ ‏ ‏وَبُؤْنَا بِالْغَضَبِ ثُمَّ قُلْنَا لَوْ دَخَلْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَبِتْنَا ثُمَّ قُلْنَا لَوْ عَرَضْنَا أَنْفُسَنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنْ كَانَتْ لَهُ تَوْبَةٌ وَإِلَّا ذَهَبْنَا فَأَتَيْنَاهُ قَبْلَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏فَخَرَجَ فَقَالَ مَنْ الْقَوْمُ قَالَ فَقُلْنَا نَحْنُ ‏ ‏الْفَرَّارُونَ ‏ ‏قَالَ لَا ‏ ‏بَلْ أَنْتُمْ ‏ ‏الْعَكَّارُونَ ‏ ‏أَنَا ‏ ‏فِئَتُكُمْ ‏ ‏وَأَنَا ‏ ‏فِئَةُ ‏ ‏الْمُسْلِمِينَ قَالَ فَأَتَيْنَاهُ حَتَّى قَبَّلْنَا يَدَهُ ‏","","",""],[5129,5129,"","আমরা একটা মোসের কথা বলেছি, যার খারাপ জীবন আছে। দশ জনের মধ্যে আমরা যেতে হবে এবং আমরা গুনছি যে সময় তিনি চলে গেছেন এবং তিনি তার জন্য প্রার্থনা করেছেন। তিনি মারা গিয়েছিলেন, তার আত্মার ইচ্ছার সঙ্গে নয় কিন্তু বছর এবং আকাশ ঈশ্বরের সঙ্গে আছে । তার সাথে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ رَاشِدٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا حُجَّاجًا عَشَرَةً مِنْ أَهْلِ ‏ ‏الشَّأَمِ ‏ ‏حَتَّى أَتَيْنَا ‏ ‏مَكَّةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ فَأَتَيْنَاهُ فَخَرَجَ إِلَيْنَا ‏ ‏يَعْنِي ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَالَتْ شَفَاعَتُهُ دُونَ حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ فَقَدْ ضَادَّ اللَّهَ فِي أَمْرِهِ وَمَنْ مَاتَ وَعَلَيْهِ دَيْنٌ فَلَيْسَ بِالدِّينَارِ وَلَا بِالدِّرْهَمِ وَلَكِنَّهَا الْحَسَنَاتُ وَالسَّيِّئَاتُ وَمَنْ خَاصَمَ فِي بَاطِلٍ وَهُوَ يَعْلَمُهُ لَمْ يَزَلْ فِي سَخَطِ اللَّهِ حَتَّى يَنْزِعَ وَمَنْ قَالَ فِي مُؤْمِنٍ مَا لَيْسَ فِيهِ أَسْكَنَهُ اللَّهُ ‏ ‏رَدْغَةَ الْخَبَالِ ‏ ‏حَتَّى يَخْرُجَ مِمَّا قَالَ ‏","","",""],[5130,5130,"","আমরা সবাই ঈশ্বরের অনুগ্রহের কথা বলেছি, মানে ছেলে ছেলে, ঈশ্বর তাকে বলেছেন যে কার হাত কাটা হয়েছে তার দোষ দেয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏نَزَعَ ‏ ‏يَدًا مِنْ طَاعَةٍ فَلَا حُجَّةَ لَهُ يَوْمَ الْقِيَامَةِ وَمَنْ مَاتَ مُفَارِقًا لِلْجَمَاعَةِ فَقَدْ مَاتَ مِيتَةً جَاهِلِيَّةً ‏","","",""],[5131,5131,"","আমরা সবাই ঈশ্বরের সন্তানের অনুগ্রহ নিয়ে কথা বলেছি, ঈশ্বর তাকে মানুষের কাছে হস্তান্তর করেছেন, আর তিনি একশ লোক যাদের কাছে একজন ভ্রমণ করতে পারবেন না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا النَّاسُ كَإِبِلٍ مِائَةٍ لَا تَكَادُ تَجِدُ فِيهَا رَاحِلَةً ‏","","",""],[5132,5132,"","আমরা সবাই বলেছি, ঈশ্বর এটা কিভাবে করেছেন, সে এটা পড়বে অথবা মানুষ শপথ জিততে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ هَذِهِ الْآيَةَ ‏ { ‏يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ ‏} ‏قَالَ ‏ ‏يَقُومُونَ حَتَّى يَبْلُغَ ‏ ‏الرَّشْحُ ‏ ‏آذَانَهُمْ ‏","","",""],[5133,5133,"","বাবার চেয়ে বাবার সাথে সময় কাটাতে হবে। বাবার জন্য আমি একটা বাচ্চা ছিলাম। ঈশ্বরের শান্তি হবে, তুমি ঘরে আছ, তারা তোমার থেকে কিছু স্প্রে করবে না।","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ الْبَاهِلِيُّ أَبُو الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَعْزَبَ شَابًّا أَبِيتُ فِي الْمَسْجِدِ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ الْكِلَابُ تُقْبِلُ ‏ ‏وَتُدْبِرُ ‏ ‏فِي الْمَسْجِدِ فَلَمْ يَكُونُوا يَرُشُّونَ شَيْئًا مِنْ ذَلِكَ ‏","","",""],[5134,5134,"","আমরা সবাই কথা বলেছি, আমরা ইতিমধ্যে একটি কাজ করেছি, ঈশ্বর বলেন তিনি প্রভুর ইচ্ছা থেকে বেরিয়ে এসেছেন, ঈশ্বর তাকে উদ্ধার করেছেন এবং তাকে ছেড়ে দিয়েছেন। আমি সামনে এগিয়ে যাচ্ছি এবং তার আগে তাকে নিয়ে যাচ্ছি। ঈশ্বর তাকে এবং প্রভু আদেশ দিয়েছেন যে, তিনি তার অনুগ্রহ লাভ করবেন । আমি এক ছেলেকে বলতে শুনেছি যে, ঈশ্বর তাকে উদ্ধার করতে এসেছেন এবং তিনি তা করবেন । সিংহাসনের কাছে তার পিপাসার্ত।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو طُعْمَةَ ‏ ‏قَالَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏لَا أَعْرِفُ ‏ ‏إِيشْ اسْمُهُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمِرْبَدِ ‏ ‏فَخَرَجْتُ مَعَهُ فَكُنْتُ عَنْ يَمِينِهِ وَأَقْبَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَتَأَخَّرْتُ لَهُ فَكَانَ عَنْ يَمِينِهِ وَكُنْتُ عَنْ يَسَارِهِ ثُمَّ أَقْبَلَ ‏ ‏عُمَرُ ‏ ‏فَتَنَحَّيْتُ لَهُ فَكَانَ عَنْ يَسَارِهِ فَأَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمِرْبَدَ ‏ ‏فَإِذَا ‏ ‏بِأَزْقَاقٍ ‏ ‏عَلَى ‏ ‏الْمِرْبَدِ ‏ ‏فِيهَا خَمْرٌ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمُدْيَةِ ‏ ‏قَالَ وَمَا عَرَفْتُ ‏ ‏الْمُدْيَةَ ‏ ‏إِلَّا يَوْمَئِذٍ فَأَمَرَ ‏ ‏بِالزِّقَاقِ ‏ ‏فَشُقَّتْ ثُمَّ قَالَ ‏ ‏لُعِنَتْ الْخَمْرُ وَشَارِبُهَا وَسَاقِيهَا وَبَائِعُهَا وَمُبْتَاعُهَا وَحَامِلُهَا وَالْمَحْمُولَةُ إِلَيْهِ وَعَاصِرُهَا وَمُعْتَصِرُهَا وَآكِلُ ثَمَنِهَا ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ يَعْنِي ابْنَ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِي طُعْمَةَ ‏ ‏مَوْلَاهُمْ ‏ ‏وَعَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ الْغَافِقِيِّ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لُعِنَتْ الْخَمْرُ عَلَى عَشَرَةِ وُجُوهٍ فَذَكَرَ الْحَدِيثَ ‏","","",""],[5135,5135,"","আমরা কথা বলেছি, বাবার সাথে কথা বলেছি, আমি নিশ্চিত না আমি বিছানায় সবচেয়ে দ্রুত কাজ করতে পারব কিনা। এটা একটা টোকেনের মত মূল্যবান জিনিস।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو طُعْمَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏إِذْ جَاءَهُ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏إِنِّي أَقْوَى عَلَى الصِّيَامِ فِي السَّفَرِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَمْ يَقْبَلْ رُخْصَةَ اللَّهِ كَانَ عَلَيْهِ مِنْ ‏ ‏الْإِثْمِ ‏ ‏مِثْلُ جِبَالِ ‏ ‏عَرَفَةَ ‏","","",""],[5136,5136,"","আমরা কথা বলেছি তোমাকে খাওয়াচ্ছে কিনা, সে বলল তার কথা শুনে ঈশ্বরের কাছে প্রার্থনা করছে যে তাকে তাকে ধরে রাখতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ إِمْسَاكِ الْكَلْبِ ‏ ‏فَقَالَ أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَمْسَكَهُ نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطَانِ ‏","","",""],[5137,5137,"","আমরা সবাই বাতাসের সাথে অনুগ্রহ নিয়ে কথা বলেছি, এমন এক ছেলে যে কিনা লাইনের মধ্যে ছিল যে ছেলে হত যে কিনা ভেঙ্গে যেত। সে এই পৃথিবীতে সে এমন করছে যে সে আমাকে বলল আমি জানি না। ঈশ্বরের কাছে জন্মগ্রহণ করা এক ছেলের সম্বন্ধে তার নিজের নাম ও তার স্বপ্ন দেখে অবাক হয়ে যায় ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ رَافِعٍ الْحَضْرَمِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فِي الْمُصَلَّى فِي الْفِطْرِ وَإِلَى جَنْبِهِ ابْنٌ لَهُ فَقَالَ لِابْنِهِ هَلْ تَدْرِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ فِي هَذَا الْيَوْمِ قَالَ لَا أَدْرِي قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَبْلَ الْخُطْبَةِ ‏","","",""],[5138,5138,"","আমরা নিশ্চিত হয়েছি যে আমরা একটি ভাল ছেলে হতে যাচ্ছি যে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আপনি একটি সমাধান তার মৃত্যু সম্পূর্ণ মহিমা.","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ وَإِذَا أُحِلْتَ عَلَى مَلِيءٍ فَاتْبَعْهُ وَلَا بَيْعَتَيْنِ فِي وَاحِدَةٍ ‏","","",""],[5139,5139,"","আমরা সবাই একটা ছেলের কথা বলেছি, ঈশ্বরের পুত্র ছাড়া আমরা ঈশ্বরের কাছে প্রার্থনা করেছি। সে তাকে জানে আর সে তোমার বাড়িতে গুলি করবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبِيتَنَّ النَّارُ فِي بُيُوتِكُمْ فَإِنَّهَا عَدُوٌّ ‏","","",""],[5140,5140,"","আমরা একটা ছেলের কথা বলেছি, যে আমার বাবা, সে একটা দাফনের সময় আমার সাথে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ الْمَغَانِمَ تُجَزَّأُ خَمْسَةَ أَجْزَاءٍ ثُمَّ ‏ ‏يُسْهَمُ ‏ ‏عَلَيْهَا ‏ ‏فَمَا كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُوَ لَهُ يَتَخَيَّرُ ‏","","",""],[5141,5141,"","আমরা একটি ছেলে কথা বলেছি, যে আমাদের সাথে কথা বলেছে কিন্তু ঈশ্বর পৃথিবীর শান্তি জয় করেছেন। ঈশ্বর হয়তো তার শান্তি ও শান্তি রক্ষা করেছেন। সে তার ভাইকে বিক্রি করে দিয়েছে, ধনী আর গর্ভজাত নয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا سَأَلَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏بَيْعِ الْمُزَايَدَةِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبِيعَ أَحَدُكُمْ عَلَى بَيْعِ أَخِيهِ إِلَّا الْغَنَائِمَ وَالْمَوَارِيثَ ‏","","",""],[5142,5142,"","আমরা আমাদের জীবনের এক দীর্ঘ সময় ধরে কথা বলেছিলাম, যা আমাদের কাছে ঘটেছিল । তার প্রার্থনা, রাত দুটো রাস্তা, তাই সকালে আপনি সকালে, দিনের আলো, আলোর আলোর আলো, আলোর আলোর আলোর আলো। হালকা আলোর আলো নিভিয়ে দেওয়া আলোক আলোকর আলোর আলোকর আলোর আলোক","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ صَلَاةِ اللَّيْلِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ اللَّيْلِ وَأَنَا بَيْنَهُمَا فَقَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ ‏ ‏فَبَادِرْ ‏ ‏الصُّبْحَ بِرَكْعَةٍ وَرَكْعَتَيْنِ قَبْلَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏","","",""],[5143,5143,"","আমরা এমন এক ছেলের কথা বলেছিলাম, যাকে ঈশ্বরকে বলা হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَاعَنَ ‏ ‏بَيْنَ رَجُلٍ وَامْرَأَتِهِ وَأَلْحَقَ الْوَلَدَ بِأُمِّهِ وَكَانَ ‏ ‏انْتَفَى ‏ ‏مِنْ وَلَدِهَا ‏","","",""],[5144,5144,"","আমরা বাবা আমার খালি ঘুমের ছেলেকে নিয়ে কথা বলেছিলাম যে, ঈশ্বর একটা ছেলের জন্য একটা অনুগ্রহ নিয়ে আসবেন, যে কিনা অতিক্রম করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏مِنْ الْحَجَرِ إِلَى الْحَجَرِ ‏","","",""],[5145,5145,"","আমি যখন আমার হাত ফিরে পেতে চেষ্টা করা একজন বেপটিস্টের কথা বলেছিলাম, তখন আমার বাবা খুব ভাল ছিলেন এবং তারপর একটি ছেলের যুদ্ধাপন্ন ছেলেকে আমি বলেছিলাম যে আমার প্রার্থনা করা উচিত ঈশ্বর সব কিছু তার কাছে দিয়েছেন আর তাকে কিভাবে হত্যা করতে বলা হয়েছে সে তার সর্বোচ্চ চেষ্টা করেছে আর তার ডান কাজের জন্য তিনি যে সাল্মের উপর করুণা দেখিয়েছেন তা তিনি উল্লেখ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدِ بْنِ الْأَنْدَرَاوَرْدِيِّ ‏ ‏مَوْلَى ‏ ‏بَنِي لَيْثٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى بْنِ عُمَارَةَ بْنِ أَبِي حَسَنٍ الْأَنْصَارِيِّ ثُمَّ الْمُحَارِبِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَخْبِرْنِي عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ كَانَتْ قَالَ ‏ ‏فَذَكَرَ التَّكْبِيرَ كُلَّمَا وَضَعَ رَأْسَهُ وَكُلَّمَا رَفَعَهُ وَذَكَرَ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ عَنْ يَمِينِهِ السَّلَامُ عَلَيْكُمْ عَنْ يَسَارِهِ ‏","","",""],[5146,5146,"","আমরা বাবা বাবার সাথে একটা স্বপ্নে একটা ছেলে নিয়ে কথা বলেছিলাম যে ঈশ্বর আছে। ঈশ্বরের আছে এবং সে আসছে এবং হেঁটে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ بِلَالٍ يَعْنِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5147,5147,"","আমরা আমার স্বপ্নের কথা বলেছিলাম, ঈশ্বরের ছেলের কথা আমাদের বলা উচিত। ঈশ্বর তা তুলে দেবেন না। যদি তুমি অত্যাচার করো তাহলে তুমি পাপ স্বীকার করবে না। তাদের আনতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُوا عَلَى هَؤُلَاءِ الْقَوْمِ الْمُعَذَّبِينَ إِلَّا أَنْ تَكُونُوا بَاكِينَ فَإِنْ لَمْ تَكُونُوا بَاكِينَ فَلَا تَدْخُلُوا عَلَيْهِمْ أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَهُمْ ‏","","",""],[5148,5148,"","আমরা একটা স্বপ্নের বিষয়ে বলেছিলাম, যে কিনা অতিক্রম করেছে, তাকে ঈশ্বরের কাছে সমর্পণ করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏ذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ ‏ ‏يُخْدَعُ فِي الْبَيْعِ فَقَالَ لَهُ ‏ ‏مَنْ بَايَعْتَ فَقُلْ لَا ‏ ‏خِلَابَةَ ‏ ‏فَكَانَ يَقُولُ ‏ ‏إِذَا بَايَعَ لَا ‏ ‏خِلَابَةَ ‏ ‏وَكَانَ فِي لِسَانِهِ ‏ ‏رُتَّةٌ ‏","","",""],[5149,5149,"","তার মুখোমুখি হওয়ার পর সেই রহস্যটি তার কাছে এসেছিল এবং বলেছিল যে, ভাববাদী তার কাছে এসে আপনাকে চলে যেতে বলেছেন । গোপন কথা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ فِي السَّفَرِ حَيْثُمَا تَوَجَّهَتْ بِهِ وَذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَصْنَعُ ذَلِكَ فِي السَّفَرِ ‏","","",""],[5150,5150,"","আমরা বাবাকে বলেছিলাম, সে নাকি এখন থেকে একটা আংটি পরে আছে, আর সে বলবে ঈশ্বর এটা করেছে আর সে পৌঁছে দিয়েছে তার কাছে, সবাই ভয় পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْبَسُ خَاتَمًا مِنْ ذَهَبٍ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَبَذَهُ وَقَالَ ‏ ‏لَا أَلْبَسُهُ أَبَدًا قَالَ فَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[5151,5151,"","গৌরবের জন্য তিনি আমাকে সেই লোকেদের বলেছিলেন, যারা তা হারিয়ে ফেলেছে আর পরে তিনি বলেছিলেন যে, যখন তাকে ছেড়ে দেওয়া হবে, তখন তিনি বলেছিলেন যে, তিনি যখন তাকে ছেড়ে দেবেন, তখন তিনি তা করবেন । ( গীতসংহিতা ১১৯: ১৬৬) ঈশ্বরের মুখনির্গত বাক্য থেকে তিনি হয়তো প্রার্থনায় তাঁর সামনে যে - প্রার্থনা করেছিলেন, সেই সম্বন্ধে কেউ কখনও মুখ ফিরিয়ে নিতে পারেননি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ وَهُوَ ‏ ‏يُصَلِّي بَيْنَ يَدَيْ النَّاسِ فَحَتَّهَا ثُمَّ قَالَ حِينَ انْصَرَفَ مِنْ الصَّلَاةِ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا كَانَ فِي الصَّلَاةِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قِبَلَ وَجْهِهِ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏أَحَدٌ قِبَلَ وَجْهِهِ فِي الصَّلَاةِ ‏","","",""],[5152,5152,"","আমি আমার ভাইয়ের স্বপ্ন নিয়ে কথা বলেছি ভালো কাপুরুষকে সাহায্য করার জন্য। লর্ড তার কাছে প্রার্থনা করে... ...আর একটা কঠিন ফ্যাশনের মধ্যে একটা যুদ্ধবাজ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادَّهَنَ بِزَيْتٍ غَيْرِ ‏ ‏مُقَتَّتٍ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[5153,5153,"","আমি আমার বাবার মৃত্যুর পর আমার বাবার সাথে সাহায্য করার চেষ্টা করেছি। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং বোমা বর্ষণের জন্য আত্মসমর্পণ করবেন এবং প্রভু শপথ গ্রহণ করবেন। সূর্য, মেয়েটা এখানে শয়তানের বানর খেয়ে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ أَبِي الصَّهْبَاءِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَجْرَ ثُمَّ سَلَّمَ فَاسْتَقْبَلَ مَطْلِعَ الشَّمْسِ فَقَالَ ‏ ‏أَلَا إِنَّ ‏ ‏الْفِتْنَةَ ‏ ‏هَاهُنَا أَلَا إِنَّ ‏ ‏الْفِتْنَةَ ‏ ‏هَاهُنَا حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[5154,5154,"","আমরা আশা করছি আমার মায়ের ভাগ্যের কথা দুই বছর ধরে শুনে আসছি, সে বলেছিল, সে ভাববাদীর কাছে প্রার্থনা করেনি আর যদি না করেও তাহলে সে আত্মসমর্পণ করবে সে ফিরে আসবে আর তোমাকে খুজে পাবে দুই মাস আগে সে একটা ছেলেকে খুঁজে পাবে, যে কখনো তার নাম দেয় নি। মানে, আমি জানি না।","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ ‏ ‏لَمْ يَصُمْهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَا ‏ ‏عُمَرُ ‏ ‏وَلَا ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَمْ يَصُمْهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَا ‏ ‏عُمَرُ ‏ ‏وَلَا ‏ ‏عُثْمَانُ ‏ ‏يَعْنِي يَوْمَ ‏ ‏عَرَفَةَ ‏","","",""],[5155,5155,"","আমরা ঈশ্বরের দোহাইর জন্য ভালো থাকার কথা বলেছিলাম, ঈশ্বর দাবি করেছেন এবং তাদের কানে আশ্বস্ত করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسَمَ فِي ‏ ‏النَّفَلِ ‏ ‏لِلْفَرَسِ ‏ ‏سَهْمَيْنِ ‏ ‏وَلِلرَّجُلِ ‏ ‏سَهْمًا ‏","","",""],[5156,5156,"","আমরা একটা বাচ্চা ছেলের সঙ্গে কথা বলেছিলাম, যিনি আমাদের সঙ্গে কথা বলেছিলেন । গোপন কথা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ فِي السَّفَرِ أَيْنَمَا تَوَجَّهَتْ بِهِ قَالَ وَذَكَرَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ فِي السَّفَرِ ‏","","",""],[5157,5157,"","ঈশ্বরের কাছে প্রেরিত একজন পুত্র যে ঈশ্বরের কাছে পাঠানো হয়েছে তার নামে শপথ করে বলা হয়েছে যে, সে তার ইচ্ছা পালন করতে আদেশ দিয়েছে । তার শক্তি আর দুনিয়ার বিষের আগে। ঈশ্বর সেটা জানেন। আমি বলবো এটা তার হাতে আছে আর এটা ঈশ্বরের কাছে দিয়ে যেতে হবে। আমি দুঃখিত করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি করি। ঈশ্বরের অনুগ্রহে প্রার্থনা করা হয়েছে, যতক্ষণ না তিনি আত্মসমর্পণ না করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ هَذِهِ الْآيَةَ ذَاتَ يَوْمٍ عَلَى الْمِنْبَرِ ‏ { ‏وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ ‏} ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَكَذَا بِيَدِهِ وَيُحَرِّكُهَا يُقْبِلُ بِهَا وَيُدْبِرُ يُمَجِّدُ الرَّبُّ نَفْسَهُ أَنَا الْجَبَّارُ أَنَا الْمُتَكَبِّرُ أَنَا الْمَلِكُ أَنَا الْعَزِيزُ أَنَا الْكَرِيمُ فَرَجَفَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمِنْبَرُ حَتَّى قُلْنَا لَيَخِرَّنَّ بِهِ ‏","","",""],[5158,5158,"","আমরা একটা ছেলেকে খুঁজে বের করার চেষ্টা করেছি, যে বলেছে আমি একটা ছেলেকে জিজ্ঞেস করব যে খারাপ কাজ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الْأَوْعِيَةِ قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ تِلْكَ الْأَوْعِيَةِ ‏","","",""],[5159,5159,"","আমরা বাপ্তিস্মের ব্যাপারে কথা বলেছি কিন্তু আমাদের বলার আছে যে, নগ্ন হওয়ার চেষ্টা করছে। আমি এমন একটা ছেলেকে জিজ্ঞেস করবো যে ঈশ্বরকে এটা করতে বলবে এবং তোমার ভালবাসার মুখে সেটা স্বপ্নে দেখতে চাই। ঈশ্বর আমার প্রতি দয়া করে। ঈশ্বর তাঁর পতাকার মাধ্যমে তাকে শিক্ষা দিয়েছেন এবং তিনি তাকে শিক্ষা দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَبِيبٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْتَمِرُ فِي رَجَبٍ قَالَ نَعَمْ فَأَخْبَرَ بِذَلِكَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ يَرْحَمُ اللَّهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةً إِلَّا وَهُوَ مَعَهُ وَمَا اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجَبٍ قَطُّ ‏","","",""],[5160,5160,"","আমরা উড়ন্ত উড়ন্ত ছেলেটির কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏حَفِظْتُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ رَكَعَاتٍ رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ وَرَكْعَتَيْنِ قَبْلَ الصُّبْحِ ‏","","",""],[5161,5161,"","আমরা হামাদ বাংবার বা সিগনের কথা বলেছি। আমি বলেছিলাম যে একটি ছেলের জন্য কি কাজ করা যায়, যার জন্য তাকে এটা করতে বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا أَوْ يَقُولُ أَحَدُهُمَا لِصَاحِبِهِ اخْتَرْ ‏","","",""],[5162,5162,"","আমি বাবার সাথে ঝগড়া করার চেষ্টা করার কথা বলেছিলাম, ঈশ্বর আমাকে আশীর্বাদ করুন, যে জীবন দিয়ে তুমি আমাকে কল করো না... ...যদি আমি ঈশ্বরের ইচ্ছা শুনি, ঈশ্বর কখনো প্রার্থনা গ্রহণ করবেন না। একটা পাখি দিয়ে যে পাথরে আঘাত করে, সে কখনো আঘাত পায়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏يَعُودُهُ فَقَالَ مَا لَكَ لَا تَدْعُو لِي قَالَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَقْبَلُ صَلَاةً بِغَيْرِ طُهُورٍ وَلَا ‏ ‏صَدَقَةً ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏ ‏وَقَدْ كُنْتَ عَلَى ‏ ‏الْبَصْرَةِ ‏ ‏يَعْنِي عَامِلًا ‏","","",""],[5163,5163,"","আমরা আমার বাবার সাথে কথা বলেছি যে আমার বাবার ছেলে একটা ছেলে ছেলে সম্পর্কে শুনতে পেয়েছে। আমি তাকে তার প্রভুর অনুগ্রহে চলে যাওয়ার কথা বলবো। আর যদি তুমি এটা না কর, তাহলে নকশা করোনি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنِ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏سَأَلَهُ عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏قَالَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَمَعَ ‏ ‏عُمَرَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَمَعَ ‏ ‏عُثْمَانَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَأَنَا لَا أَصُومُهُ وَلَا آمُرُكَ وَلَا ‏ ‏أَنْهَاكَ إِنْ شِئْتَ فَصُمْهُ وَإِنْ شِئْتَ فَلَا تَصُمْهُ ‏","","",""],[5164,5164,"","আমার বাবার সাথে আমার ভালো সম্পর্ক থাকার কথা বলেছিলাম। যদি ছেলে পাশ করে, সে এমন করতো না, সে এটা করতো না। আমাদের দেখে যেতে হবে এবং তাকে ক্ষমার জায়গা দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ الرَّحْمَنِ الْمُعَاوِيِّ ‏ ‏أَنَّ رَجُلًا صَلَّى إِلَى جَنْبِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَجَعَلَ يَعْبَثُ بِالْحَصَى فَقَالَ لَا تَعْبَثْ بِالْحَصَى فَإِنَّهُ مِنْ الشَّيْطَانِ وَلَكِنْ اصْنَعْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ قَالَ هَكَذَا ‏ ‏وَأَرَانَا ‏ ‏وُهَيْبٌ ‏ ‏وَصَفَهُ ‏ ‏عَفَّانُ ‏ ‏وَضَعَ يَدَهُ الْيُسْرَى وَبَسَطَ أَصَابِعَهُ عَلَى رُكْبَتِهِ الْيُسْرَى وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى رُكْبَتِهِ الْيُمْنَى وَكَأَنَّهُ عَقَدَ وَأَشَارَ بِالسَّبَّابَةِ ‏","","",""],[5165,5165,"","আমরা একটি মহান আশীর্বাদের সাথে কথা বলেছি এবং আমার ভালোবাসার সেরা ফলটি করেছি। যে ছেলে ঈশ্বরের কাছে প্রার্থনা করেছে, তার কাছে প্রার্থনা করেছে এবং আমি যা কিছু করি তার আগে কখনো দেখা হবে না। আর তার ইচ্ছা ছিল তার ছেলে বড় হয়ে উঠে বলছে যে সে গুলি দিয়েছে আর হারটা পৃথিবীর শেষ প্রান্ত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عُمْرَى ‏ ‏وَلَا ‏ ‏رُقْبَى ‏ ‏فَمَنْ ‏ ‏أُعْمِرَ ‏ ‏شَيْئًا أَوْ ‏ ‏أُرْقِبَهُ ‏ ‏فَهُوَ لَهُ حَيَاتَهُ وَمَمَاتَهُ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏وَالرُّقْبَى ‏ ‏هِيَ لِلْآخِرِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏مِنِّي وَمِنْكَ ‏","","",""],[5166,5166,"","আমরা দুজন সালমোনসের কথা বলেছি... ...যার মানে হচ্ছে হিংসার ছেলে, ঈশ্বর তাকে একটা মই দিয়েছেন তার সাবেক স্ত্রী বলেছেন যে তারা আপনাকে পরাজিত করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏قَالَ قَدْ زَعَمُوا ذَلِكَ ‏","","",""],[5167,5167,"","আমি যখন আমার মায়ের সঙ্গে কথা বলেছিলাম, তখন আমার মা মারা যান ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ ‏ ‏أَوْ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏يُنَادِي بِلَيْلٍ ‏ ‏فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5168,5168,"","আমরা একটা বাচ্চা নিয়ে কথা বলেছিলাম যখন আমরা ঈশ্বরের সাথে কথা বলেছিলাম, ঈশ্বরের ভাগ্য খারাপ হয়ে গেছে আর আমরা দু'জন ঋণের হাত থেকে বেঁচে থাকতে পারিনি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَنَاجَى اثْنَانِ دُونَ وَاحِدٍ ‏","","",""],[5169,5169,"","আমরা একটি বাচ্চা নিয়ে কথা বলেছি যখন আমরা ঈশ্বরের সাথে কথা বলেছিলাম, ঈশ্বরের উত্তর আছে আর তাকে গ্রেফতার করা না হওয়া পর্যন্ত এটা বিক্রি করে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى يَقْبِضَهُ ‏","","",""],[5170,5170,"","আমরা ঈশ্বরের প্রিয় পুত্র হওয়ার কথা বলেছি কিন্তু ঈশ্বরের একটা ছেলে আছে, ঈশ্বর তাকে আদেশ দিয়েছেন আর সে তার প্রভুর কাছে আত্মসমর্পণ করবে, আমাদের যাদের ছেড়ে দিতে হবে না। তাদের কাছে ব্যাখ্যা করতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَلْبَسَ الْمُحْرِمُ ثَوْبًا صُبِغَ ‏ ‏بِوَرْسٍ ‏ ‏أَوْ ‏ ‏زَعْفَرَانٍ ‏ ‏وَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَكُنْ لَهُ نَعْلَانِ فَلْيَلْبَسْ الْخُفَّيْنِ وَلْيَقْطَعْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[5171,5171,"","আমরা একটা বাচ্চা থাকার কথা বলেছিলাম, যখন আমরা ঈশ্বরের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ إِلَى الْمَشْرِقِ وَيَقُولُ ‏ ‏هَا إِنَّ الْفِتَنَ هَاهُنَا إِنَّ الْفِتَنَ هَاهُنَا حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[5172,5172,"","আমরা এমন এক ছেলেকে শাস্তি দেবার চেষ্টা করেছি, যে তার কথা শোনে, যে তার ভাষায় বলে, তার প্রতিবেশী এবং ডাক্তার এবং ভুয়া এবং শিকারীদের হাতে তুলে দেবার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَمَرَ أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏فِي الْأَسْقِيَةِ ‏","","",""],[5173,5173,"","আমরা একটি বাচ্চা সন্তান জন্ম দেয়ার কথা বলেছিলাম, যে কিনা গডের বাবা ছিল, আর সে তার জন্য প্রার্থনা করতো... ...আর সে বলেছিল যে সে নাকি শেষ বারের মতো মুক্ত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لَيْلَةِ الْقَدْرِ قَالَ ‏ ‏تَحَرَّوْهَا فِي السَّبْعِ الْأَوَاخِرِ ‏","","",""],[5174,5174,"","আমরা কালো বাবার কাছ থেকে জয়ের চেষ্টা করেছি, যে আমাদের সাথে কথা বলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যারা আমাদের কাছে লুকানোর এবং ভিন্নমত পোষণ না করে তাদের কাছে আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ أَبُو الْأَسْوَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَلْيَقْطَعْهُمَا مِنْ عِنْدِ الْكَعْبَيْنِ ‏","","",""],[5175,5175,"","আমরা শুনেছি দুঃখ পরিবর্তনের রীতি, যখন দুটো একটা কুত্তার বাচ্চা পাওয়া যাবে, প্রভু তার জন্য প্রার্থনা করেছিলেন আর তিনি তার আগে তাকে ধন্যবাদ জানিয়েছিলেন দিনের পর দিন দেখা গেল, ডিনারের পর তুমি ফিরে এসেছ বিস্ফোরণের আগে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ سَلْمَانَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏عَشْرُ رَكَعَاتٍ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُدَاوِمُ عَلَيْهِنَّ ‏ ‏رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ ‏","","",""],[5176,5176,"","আমরা ঈশ্বরের পর্বতের উপর শাসন করার চেষ্টা করেছি, আর সে একজন অজ্ঞান ব্যক্তি যিনি আমার প্রভুর অনুগ্রহে চলে গেছেন এবং ঈশ্বরের ইচ্ছার কথা ঘোষণা করেছেন। তাকে কিছু একটার জন্য নিয়ে যাও।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَذَكَرَ ذَلِكَ ‏ ‏عُمَرُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُرَاجِعْهَا حَتَّى تَطْهُرَ ثُمَّ لِيُطَلِّقْهَا إِنْ شَاءَ ‏","","",""],[5177,5177,"","আমরা কথা বলেছিলাম যে, যদি একটা ছেলে তার আদেশ শুনে থাকে... ...তাহলে সে এক আসল ছেলে যে বলেছে যে তুমি আমার প্রভুর কাছে গিয়েছিলে. তাকে তারপর তালাক দিয়ে দাও, সে বলেছে গুলি করেছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏طَلَّقَ ‏ ‏ابْنُ عُمَرَ ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ فَذَكَرَ ذَلِكَ ‏ ‏عُمَرُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُرَاجِعْهَا حَتَّى تَطْهُرَ ثُمَّ لِيُطَلِّقْهَا قَالَ قُلْتُ احْتُسِبَ بِهَا قَالَ ‏ ‏فَمَهْ ‏","","",""],[5178,5178,"","আমরা যে প্রথা তৈরি করেছি, আমরা তা নিয়ে কথা বলেছি, আমরা অতীত শহর নিয়ে কথা বলেছি, ঈশ্বর আমাদের ভাল সহযাত্রীদের নিয়ে এসেছেন এবং বলে যে ঈশ্বর হয়তো মারা গেছেন। তাকে জিজ্ঞেস করে সে জলদস্যুদের থেকে মুখ ফিরিয়ে নেবে... ...তোমার আর তার ভাইয়ের সাথে ষড়যন্ত্র করবে না।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَبَلَةُ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏بِالْمَدِينَةِ ‏ ‏فِي بَعْثِ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏فَأَصَابَتْنَا سَنَةٌ فَجَعَلَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ وَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَمُرُّ بِنَا فَيَقُولُ لَا ‏ ‏تُقَارِنُوا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقِرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْمِرَ الرَّجُلُ مِنْكُمْ أَخَاهُ ‏","","",""],[5179,5179,"","আমরা ক্ষমা প্রার্থনা করেছি, আমরা কয়েক মাস ধরে কথা বলেছি, এমন একজন ছেলে আছে যে ঈশ্বরকে বলার জন্য কি করে কথা বলে সে কথা বলে। ভগবানের কাছে প্রার্থনা করে তিনি তা পৌঁছে দিয়েছেন এবং বলতে চাই যে ঈশ্বর বিশ্বাস করবেন না। তিনি তার পাপ ঠিক করেছেন এবং বলেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন তিনি জানেন, আমি হয়ত তাকে কঠিন কিছু করতে রেখে যেতে পারে। এবং তিনি যদি তিনি কিছু করতে চান, আপনি একটি মহান পিতা হতে পারেন, তিনি যদি তিনি আপনাকে বলেন, আপনি জানেন যে তিনি আপনাকে একটি মহান পিতা হতে পারেন। এবং আপনি আপনার জন্য একটি মহান পিতা হতে পারেন, আপনি আপনার জন্য একটি মহান পিতা হতে পারেন। এবং আপনি আপনার জন্য আপনার জন্য একটি মহান পিতা হতে পারেন, আপনি যে আপনি একটি মহান পিতা, আপনি একটি মহান পিতা, এবং আপনি একটি মহান পিতা, এবং তিনি যে তিনি আপনার জন্য আপনার জন্য একটি মহান মহান পিতা, আপনি একটি মহান কাজ করতে পারেন। আপনি যে তিনি আপনার জন্য আপনার জন্য একটি মহান মহান মহান মহান মহান মহান মহান মহান, এবং তিনি, এবং তিনি আপনার জন্য একটি মহান, এবং তিনি যে তিনি আপনার মহান মহান মহান মহান মহান, এবং তিনি আপনার একটি মহান, এবং তিনি এই মহান মহান মহান, এবং তিনি, এবং তিনি যে তিনি আপনার একটি মহান মহান মহান মহান মহান মহান, এবং তিনি, এবং তিনি, এবং তিনি আপনার একটি মহান, এবং তিনি, তিনি, এবং তিনি এই তিনি যে তিনি আপনার একটি মহান আর তাকে রাগ করার জন্য ক্ষমা করে দিও, সে বলবে সাক্ষীরা তাদের প্রভুর কাছে মিথ্যা বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏قَالَ ‏ ‏كُنْتُ آخِذًا بِيَدِ ‏ ‏ابْنِ عُمَرَ ‏ ‏إِذْ عَرَضَ لَهُ رَجُلٌ فَقَالَ كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي النَّجْوَى يَوْمَ الْقِيَامَةِ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْنِي الْمُؤْمِنَ فَيَضَعُ عَلَيْهِ كَنَفَهُ وَيَسْتُرُهُ مِنْ النَّاسِ وَيُقَرِّرُهُ بِذُنُوبِهِ وَيَقُولُ لَهُ أَتَعْرِفُ ذَنْبَ كَذَا أَتَعْرِفُ ذَنْبَ كَذَا أَتَعْرِفُ ذَنْبَ كَذَا حَتَّى إِذَا قَرَّرَهُ بِذُنُوبِهِ وَرَأَى فِي نَفْسِهِ أَنَّهُ قَدْ هَلَكَ قَالَ فَإِنِّي قَدْ سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا وَإِنِّي أَغْفِرُهَا لَكَ الْيَوْمَ ثُمَّ يُعْطَى كِتَابَ حَسَنَاتِهِ وَأَمَّا الْكُفَّارُ وَالْمُنَافِقُونَ فَيَقُولُ الْأَشْهَادُ ‏ { ‏هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى رَبِّهِمْ أَلَا لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ ‏}","","",""],[5180,5180,"","আমরা কয়েক বছর আগে ঈশ্বরের সাথে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করতে হবে যে শহরে কে মারা যেতে পারে এবং মারা যেতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اسْتَطَاعَ أَنْ يَمُوتَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَلْيَفْعَلْ فَإِنِّي أَشْفَعُ لِمَنْ مَاتَ بِهَا ‏","","",""],[5181,5181,"","তিনি আমাকে বলেছিলেন, তিনি কোন ভালো কিছু করবেন না, যদি সে আমাকে কখনো না দেয় সাতটা খেয়ে নাও, আমি ক্লান্ত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدٍ ‏ ‏سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏ابْنَ عُمَرَ ‏ ‏فَجَعَلَ ‏ ‏يُلْقِي إِلَيْهِ الطَّعَامَ فَجَعَلَ يَأْكُلُ أَكْلًا كَثِيرًا فَقَالَ ‏ ‏لِنَافِعٍ ‏ ‏لَا تُدْخِلَنَّ هَذَا عَلَيَّ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[5182,5182,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করেছেন যে, প্রভু দৌড়ে যাবেন এবং বিশ্বাসঘাতকরা তাকে খুঁজে পাবে না ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الَّذِي يَجُرُّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5183,5183,"","আমরা একটা বাচ্চা ছেলের কথা বলেছিলাম যে আগে কখনো গডফাদার হয়ে গিয়েছিল. ঈশ্বরের নিজের পতাকা ছিল আর সে যে অফিসারদের কাছে বলেছিল তারা এটা খাবে না আর তার অজ্ঞান হয়ে যায়নি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَسْتُ آكِلَهُ وَلَا مُحَرِّمَهُ ‏","","",""],[5184,5184,"","আমরা একটি বাচ্চা নিয়ে কথা বলেছি যখন আমরা ঈশ্বরের সাথে কথা বলেছিলাম, ঈশ্বর আত্মসমর্পণ করবেন এবং পাপপ্রিয়তায় প্রবেশ না করতে পাথরে নামবেন না। আপনি সেখানে থাকবেন। আপনি সেখানে যাবেন না। আপনি একটি বাচ্চা পাবেন। আপনি একটি শিশু জন্ম পাবেন। আপনি একটি শিশু পাবেন, আপনি একটি শিশু জন্ম দিতে পারেন, এবং আপনি একটি শিশু জন্ম গ্রহণ করতে পারেন৷ আপনি একটি শিশু জন্ম গ্রহণ করা হয়৷ আপনি একটি মহান মহান মহান মহান মহান পিতা, এবং তিনি আপনার সন্তান, আপনি একটি মহান পিতা, এবং আপনার কাছে প্রার্থনা করুন, আপনি একটি মহান পিতা, আপনি আপনার সন্তান আছে একটি মহান পিতা। আপনি করতে পারেন, আপনি করতে পারেন কি কি? আপনি আপনার সন্তান আছে? আপনি কি আপনার সন্তান আছে? আপনি কি আপনার সন্তান আছে? আপনি যদি আপনি একটি মহান পিতা এবং আপনার সন্তান আছে? এবং আপনার সন্তান, আপনি কি জানেন, আপনি কি আপনার জন্য একটি মহান? এবং আপনি কি কি কি? আপনি কি কি? আপনি কি কি কি জানেন? আপনি একটি পাথরের জন্য? আপনি কি? আপনি একটি পাথরে আপ, এবং আপনার জন্য? আপনি একটি পাথরের মধ্যে থাকেন, এবং আপনার জন্য? তোমাকে গুলি করতে হবে, যেমন আমি করি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْحِجْرِ ‏ ‏لَا تَدْخُلُوا عَلَى هَؤُلَاءِ الْقَوْمِ الْمُعَذَّبِينَ إِلَّا أَنْ تَكُونُوا بَاكِينَ فَإِنْ لَمْ تَكُونُوا بَاكِينَ فَلَا تَدْخُلُوا عَلَيْهِمْ أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَهُمْ ‏","","",""],[5185,5185,"","আমরা একটি দেবতা-দানার পুত্র গ্রহণের কথা বলেছিলাম। তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন তিনি প্রার্থনা করেছিলেন তিনি রাত থেকে আকাশ উদ্ধার করবেন। তার স্মৃতিকে ডুবিয়ে দেবার জন্য এবং পড়ে যাওয়া। নিদ্রিত","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏ذَكَرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْجَنَابَةَ تُصِيبُهُ مِنْ اللَّيْلِ فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَغْسِلَ ذَكَرَهُ وَيَتَوَضَّأَ ثُمَّ يَنَامَ ‏","","",""],[5186,5186,"","আমরা এমন এক ছেলেকে শাস্তি দেয়ার চেষ্টা করেছি, যে একটি ছেলেকে বলেছে সে এটা করতে বলেছে। তাকে ছেড়ে দেওয়া হবে, তাকে দিনে দশম ঘণ্টার মধ্যে স্পর্শ করতে হবে অথবা তাকে তার শরীরে ভরতে হবে। অন্ধকার.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مُلْتَمِسَهَا فَلْيَلْتَمِسْهَا فِي الْعَشْرِ الْأَوَاخِرِ فَإِنْ عَجَزَ أَوْ ضَعُفَ فَلَا يُغْلَبْ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[5187,5187,"","আমরা আমাদের কথোপকথন সম্পর্কে কথা বলেছি এবং সে আমার নিলামের ব্যাপারে কথা বলেছে, আমি তার কাছে তার সর্বোচ্চ সুদ কামনা করব এবং তিন বছরের চ্যাম্পিয়নকে উদ্ধার করব।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏الْأَشْوَاطَ الثَّلَاثَةَ الْأُوَلَ حَوْلَ ‏ ‏الْبَيْتِ ‏","","",""],[5188,5188,"","আমরা একটা বাচ্চা ছেলের কথা বলেছিলাম যে আমাদের সাথে কথা বলেছে, ঈশ্বর তাকে টাকা শেষ করে দেবেন যতক্ষণ না পর্যন্ত না তার সালাদ শেষ হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الثَّمَرَةِ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[5189,5189,"","বাবা যখন আমাদের সামনে এগিয়ে যাচ্ছে, তখন বাবার ঘোড়া আমাদের সামনে চলে যাবে। তারা হিল আর বয়স্কদের থেকে এসেছে আর দায়িত্ব পালন করছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَيَّامٍ أَعْظَمُ عِنْدَ اللَّهِ وَلَا أَحَبُّ إِلَيْهِ مِنْ الْعَمَلِ فِيهِنَّ مِنْ هَذِهِ الْأَيَّامِ الْعَشْرِ فَأَكْثِرُوا فِيهِنَّ مِنْ التَّهْلِيلِ وَالتَّكْبِيرِ وَالتَّحْمِيدِ ‏","","",""],[5190,5190,"","আমরা আমাদের আলোচনা সম্পর্কে কথা বলেছি এবং তিনি আমাদের জন্য ভালো একটি ছেলের জন্য করেছেন যে ঈশ্বরের উপর পাশ দিয়ে গেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ ‏","","",""],[5191,5191,"","আমরা আমাদের আলোচনা সম্পর্কে কথা বলেছি এবং তিনি আমাদের জন্য করেছেন একটি ছেলে যে পাশ করেছে, ঈশ্বর আছে, এবং তিনি আমাদের আহ্বান করেছেন যারা জনতার কাছে ফিরে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ ‏","","",""],[5192,5192,"","প্রভুর প্রতি প্রভুর ভালোবাসাই আমরা বেঁচেছিলাম... ...যে রানীর ক্ষমতা পালন করেছে, সে এমন একটা ছেলে খুঁজে পেয়েছে যে তার শান্তির জন্য প্রার্থনা করতে বলেছিল সে বলেছিল যে সে সারের জন্য প্রার্থনা করেছে, পাইলটের ছেলে কঠিন দরজার দিকে যাচ্ছে, তাই সে বলে যে তুমি হয়তো জান যে আমি...","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏قَدِمَ ‏ ‏مَكَّةَ ‏ ‏فَدَخَلَ ‏ ‏الْكَعْبَةَ ‏ ‏فَبَعَثَ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏صَلَّى بَيْنَ ‏ ‏السَّارِيَتَيْنِ ‏ ‏بِحِيَالِ الْبَابِ فَجَاءَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَرَجَّ الْبَابَ رَجًّا شَدِيدًا فَفُتِحَ لَهُ فَقَالَ ‏ ‏لِمُعَاوِيَةَ ‏ ‏أَمَا إِنَّكَ قَدْ عَلِمْتَ أَنِّي كُنْتُ أَعْلَمُ مِثْلَ الَّذِي يَعْلَمُ وَلَكِنَّكَ حَسَدْتَنِي ‏","","",""],[5193,5193,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং জনতা যদি যোবেলের সঙ্গে আসে, তা হলে তিনি আত্মসমর্পণ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جِئْتُمْ الْجُمُعَةَ فَاغْتَسِلُوا ‏","","",""],[5194,5194,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং সমুদ্র বা পাথরের কাছে আমার প্রার্থনা করেছেন আর তা হল এক যুদ্ধ ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى حِمَارٍ ‏ ‏أَوْ حِمَارَةٍ ‏ ‏وَهُوَ مُتَوَجِّهٌ إِلَى ‏ ‏خَيْبَرَ ‏","","",""],[5195,5195,"","আমরা ঈশ্বরের চেয়ে ভালো একটা জায়গা নির্মাণ করেছি... ...যার কথা বলেছিলাম একজন দাস হওয়ার জন্য, ঈশ্বরের দোহাইর জন্য মানুষ কেবল তাঁর নাম এবং নামই দিয়েছে সূর্য বা তার ভাইকে আমি যা বলেছি তা দিয়ে আমি তাকে ধন্যবাদ দিয়েছি.","‏ ‏حَدَّثَنَا ‏ ‏مُعَمَّرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ أَبُو عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ النُّعْمَانِ بْنِ قُرَادٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خُيِّرْتُ بَيْنَ الشَّفَاعَةِ أَوْ يَدْخُلُ نِصْفُ أُمَّتِي الْجَنَّةَ فَاخْتَرْتُ الشَّفَاعَةَ لِأَنَّهَا أَعَمُّ ‏ ‏وَأَكْفَى أَتُرَوْنَهَا لِلْمُنَقَّيْنَ لَا وَلَكِنَّهَا لِلْمُتَلَوِّثِينَ الْخَطَّاءُونَ ‏ ‏قَالَ ‏ ‏زِيَادٌ ‏ ‏أَمَا إِنَّهَا لَحْنٌ وَلَكِنْ هَكَذَا حَدَّثَنَا الَّذِي حَدَّثَنَا ‏","","",""],[5196,5196,"","আমরা কথা বলেছি তাকে বলতে যে আমি একটা কুত্তার বাচ্চাের কথা শুনবো, ঈশ্বর তার কাছে প্রার্থনা করলেন আর বললেন বিখ্যাতরা বেড়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[5197,5197,"","বাবার স্বপ্নের চেয়ে আমরা অনেক ভালো কাজ করেছি। আমি তাকে বলতে চাই, ঈশ্বর তার জন্য প্রার্থনা করুক। আর তিনি যদি সকালে ভয় পেয়ে থাকেন, তাহলে সকালেই তার প্রতি দয়া দেখাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَنَافِعٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ رَكْعَتَانِ فَإِذَا خِفْتُمْ الصُّبْحَ ‏ ‏فَأَوْتِرُوا ‏ ‏بِوَاحِدَةٍ ‏","","",""],[5198,5198,"","সে জিজ্ঞেস করে কে পাখিকে তার টাকা কাজ করতে দেয় আর বলে সে কিছু একটা করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ الْعَصْرَ حَتَّى تَفُوتَهُ فَكَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ ‏ ‏و قَالَ ‏ ‏شَيْبَانُ ‏ ‏يَعْنِي غُلِبَ عَلَى أَهْلِهِ وَمَالِهِ ‏","","",""],[5199,5199,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং সেই সম্প্রদায়ের ভিক্ষার জন্য যারা ভিক্ষা করছিল তাদের কাছে পৌঁছে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[5200,5200,"","আমরা কথা বলেছি এই ব্যাপারে কথা বলতে চেষ্টা করার ব্যাপারে। ঈশ্বর সব গেরিলাদের কাছে এই মূল্যবোধ রাখতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ يُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ ‏","","",""]];
